INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C1','kor',2,1,'u6',1,'매체와 중요한 내용 — 글·안내판·광고·책처럼 정보를 주고받는 도구를 매체라고 하며, 매체가 무엇을 알려 주려는지(이용 방법·주의할 점·전하고 싶은 말) 살펴 중요한 내용을 찾기',ARRAY['2국02-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C2','kor',2,1,'u6',1,'보고 든 생각을 까닭과 함께 말하기 — 매체나 글을 보고 든 생각·느낌을 「왜냐하면 ~」처럼 그렇게 생각한 까닭과 함께 말하면 듣는 사람에게 더 잘 전해짐을 알기',ARRAY['2국05-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C3','kor',2,1,'u6',3,'제목으로 중요한 내용 짐작하기 — 제목에는 글에서 가장 중요한 내용이 담겨 있으므로 제목을 보고 글이 무엇을 알려 줄지 짐작하고, 글의 내용에 어울리는 제목을 고르기',ARRAY['2국02-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C4','kor',2,1,'u6',3,'자주 나오는 낱말 찾기 — 글에 여러 번 나오고 제목과 관련 있는 낱말이 중요한 낱말임을 알고, 한 번만 나오거나 글과 상관없는 낱말과 가려 찾기',ARRAY['2국02-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C5','kor',2,1,'u6',3,'중심 문장 찾고 중요한 내용 정리하기 — 각 부분에서 가장 중요한 문장(중심 문장)을 찾고, 예를 들거나 까닭을 덧붙인 문장과 가려, 중심 문장을 모아 글의 중요한 내용을 정리하기',ARRAY['2국02-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C6','kor',2,1,'u6',7,'인물의 말에서 생각 찾기 — 글 속 인물이 한 말에서 무엇을 하고 싶은지·어떻게 하자고 하는지 인물의 생각을 찾고, 인물마다 생각이 다름을 알기',ARRAY['2국02-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C7','kor',2,1,'u6',7,'생각의 까닭 찾기 — 생각 뒤에 나오는 좋은 점·옳은 점(「~해서」·「~거든」·「~니까」)이 까닭임을 알고, 생각과 까닭을 한 쌍으로 짝지어 찾기',ARRAY['2국02-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C8','kor',2,1,'u6',9,'자신의 생각을 까닭과 함께 예의 바르게 표현하기 — 인물의 생각과 까닭을 먼저 파악한 뒤 「나는 ~라고 생각해. 왜냐하면 ~거든.」처럼 내 생각과 까닭을 예의 바르게 말하고 쓰며, 나와 다른 생각도 존중하기',ARRAY['2국05-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C9','kor',2,1,'u6',12,'책을 소개하며 생각 나누기 — 책 소개 상자의 여러 면에 제목·인상 깊은 장면·기억에 남는 문장·읽고 든 생각이나 느낌을 담아 소개하고, 같은 책에도 생각이 다를 수 있음을 알기',ARRAY['2국06-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C10','kor',2,1,'u6',14,'토박이말 알기 — 까치밥·벗·여우비·단비·함박눈·나들이처럼 예부터 우리말로 써 온 정겨운 토박이말의 뜻을 알고 알맞게 쓰기',ARRAY['2국04-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X01','kor',2,'u6',ARRAY['K2-1-u6-C1']::text[],'정보를 주고받지 않는 물건(지우개·우산·의자)을 매체로 여긴다','「무엇을 알려 주지?」 물어서 대답이 나오는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X02','kor',2,'u6',ARRAY['K2-1-u6-C1']::text[],'매체마다 알려 주는 내용을 헷갈린다(안내판이 이야기를 들려준다, 광고가 이용 방법만 알려 준다)','그 매체를 어디서 보았는지 떠올리고 무엇이 적혀 있었는지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X03','kor',2,'u6',ARRAY['K2-1-u6-C1','K2-1-u6-C3','K2-1-u6-C5']::text[],'사소하거나 글과 상관없는 것(색깔·날씨·글자 모양)을 중요한 내용으로 고른다','「이 글은 무엇을 알려 주려고 썼지?」 먼저 말하고 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X04','kor',2,'u6',ARRAY['K2-1-u6-C3']::text[],'제목을 살피지 않고 내용을 짐작하거나, 글의 내용과 어울리지 않는 제목을 고른다','제목을 소리 내어 읽고 「무엇에 대한 글일까?」 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X05','kor',2,'u6',ARRAY['K2-1-u6-C4']::text[],'한 번만 나오거나 글과 상관없는 낱말을 자주 나오는 중요한 낱말로 고른다','낱말이 나올 때마다 손가락으로 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X06','kor',2,'u6',ARRAY['K2-1-u6-C5']::text[],'예를 들거나 까닭을 덧붙인 문장을 중심 문장으로 고르거나, 한 부분의 내용만 글 전체의 중요한 내용으로 여긴다','「이 부분에서 가장 하고 싶은 말은?」 한 문장으로 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X07','kor',2,'u6',ARRAY['K2-1-u6-C5','K2-1-u6-C6','K2-1-u6-C7']::text[],'글에 없는 내용을 있다고 하거나 글의 내용을 놓친다','글에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X08','kor',2,'u6',ARRAY['K2-1-u6-C6','K2-1-u6-C7']::text[],'인물을 뒤바꿔 다른 인물의 생각·까닭을 말한다','말한 사람 이름에 동그라미 치고 그 말만 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X09','kor',2,'u6',ARRAY['K2-1-u6-C7','K2-1-u6-C2']::text[],'생각과 까닭을 헷갈리거나, 까닭이 아닌 말(「오늘은 화요일」·「내 신발은 파란색」)을 까닭으로 여긴다','「왜?」 하고 물었을 때 대답이 되는 말인지 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X10','kor',2,'u6',ARRAY['K2-1-u6-C2','K2-1-u6-C8']::text[],'까닭 없이 생각만 말하거나 「그냥」·「좋으니까」처럼 까닭이 드러나지 않게 말한다','「왜냐하면 ~거든」을 꼭 붙여 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X11','kor',2,'u6',ARRAY['K2-1-u6-C8']::text[],'큰 소리로 우기거나 무례한 말로 생각을 전하고, 친구의 말을 끝까지 듣지 않는다','「나는 ~라고 생각해」로 시작하고 친구 말이 끝날 때까지 기다리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X12','kor',2,'u6',ARRAY['K2-1-u6-C8','K2-1-u6-C9']::text[],'나와 생각이 다르면 틀렸다고 여기거나 친구의 생각을 무시한다','「너는 그렇게 생각하는구나. 까닭이 뭐야?」 하고 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X13','kor',2,'u6',ARRAY['K2-1-u6-C9']::text[],'책 소개와 상관없는 내용(시험 점수·전화번호·비밀번호·날씨)을 책 소개 상자에 담는다','「이 내용이 책을 알려 주나?」 하나씩 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X14','kor',2,'u6',ARRAY['K2-1-u6-C9']::text[],'책 소개 상자의 면과 담을 내용을 헷갈리거나, 줄거리만 쓰고 읽고 든 생각·느낌을 빠뜨린다','앞면 → 문장 → 생각 차례로 상자를 돌려 가며 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X15','kor',2,'u6',ARRAY['K2-1-u6-C10']::text[],'토박이말의 뜻을 바꿔 알거나 글자 모양만 보고 짐작한다(여우비 → 여우가 오는 날, 까치밥 → 까치가 지은 밥)','토박이말이 쓰이는 때를 그림으로 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X16','kor',2,'u6',ARRAY['K2-1-u6-C1','K2-1-u6-C2','K2-1-u6-C3','K2-1-u6-C4','K2-1-u6-C5','K2-1-u6-C6','K2-1-u6-C7','K2-1-u6-C8','K2-1-u6-C9','K2-1-u6-C10']::text[],'묻는 말을 거꾸로 읽는다 — 알맞지 않은↔알맞은, 잘못↔바르게, 아닌↔맞는','물음의 「않은·잘못·아닌」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#1','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],true,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"안내판","correct":true},{"t":"지우개","mis":"K2-1-u6-X01"},{"t":"우산","mis":"K2-1-u6-X01"}],"explanation":["안내판은 이용 방법과 주의할 점을 알려 주는 매체예요.","지우개와 우산은 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오면 매체예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"광고","correct":true},{"t":"의자","mis":"K2-1-u6-X01"},{"t":"신발","mis":"K2-1-u6-X01"}],"explanation":["광고는 사람들에게 전하고 싶은 말을 알려 주는 매체예요.","의자와 신발은 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오면 매체예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#2','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',1,'mc','auto','안내판을 읽고 답해 보세요. 이 안내판이 알려 주는 것은 무엇인가요?',ARRAY['K2-1-u6-X03']::text[],true,'{"seq":2,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"안내판을 읽고 답해 보세요. 이 안내판이 알려 주는 것은 무엇인가요?","options":[{"t":"놀이터를 이용할 때 지킬 일","correct":true},{"t":"놀이터 미끄럼틀의 색깔","mis":"K2-1-u6-X03"},{"t":"오늘의 날씨","mis":"K2-1-u6-X03"}],"explanation":["안내판에는 놀이터를 이용할 때 지킬 일이 적혀 있어요.","미끄럼틀 색깔이나 날씨는 안내판에 없어요.","매체가 무엇을 알려 주려는지 생각해요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"},"variant_rule":{"alt":[{"stem":"광고를 읽고 답해 보세요. 이 광고가 알려 주는 것은 무엇인가요?","options":[{"t":"도서관에서 책 잔치가 열린다는 것","correct":true},{"t":"도서관 건물의 색깔","mis":"K2-1-u6-X03"},{"t":"내일 비가 온다는 것","mis":"K2-1-u6-X03"}],"explanation":["광고는 도서관 책 잔치를 알리고 있어요.","건물 색깔이나 날씨는 광고에 없어요.","매체가 무엇을 알려 주려는지 생각해요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#3','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C2',1,'ox','auto','매체를 보고 든 생각을 말할 때 그렇게 생각한 까닭을 함께 말하면 더 잘 전해져요.',ARRAY['K2-1-u6-X10']::text[],true,'{"seq":3,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"매체를 보고 든 생각을 말할 때 그렇게 생각한 까닭을 함께 말하면 더 잘 전해져요.","answer":"O","reason_options":[{"t":"까닭을 들으면 듣는 사람이 내 생각을 더 잘 이해하니까","correct":true},{"t":"까닭은 말하지 않아야 더 멋지니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["「왜냐하면 ~」처럼 까닭을 붙이면 생각이 더 잘 전해져요.","까닭이 없으면 듣는 사람이 왜 그런지 알기 어려워요.","생각과 까닭을 함께 말해요."],"variant_rule":{"alt":[{"stem":"「이 안내판은 좋아.」라고만 말해도 내 생각이 충분히 전해져요.","answer":"X","reason_options":[{"t":"왜 좋은지 까닭을 덧붙여야 생각이 잘 전해지니까","correct":true},{"t":"생각은 짧을수록 언제나 잘 전해지니까","mis":"K2-1-u6-X10"}],"explanation":["「좋아.」만으로는 왜 좋은지 알 수 없어요.","「위험한 일을 알려 줘서 좋아.」처럼 까닭을 붙여요.","생각과 까닭을 함께 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#4','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',1,'mc','auto','안내판을 세워 두는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X02']::text[],true,'{"seq":4,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"안내판을 세워 두는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"이용 방법과 주의할 점을 알려 주려고","correct":true},{"t":"친구의 생일을 알려 주려고","mis":"K2-1-u6-X02"},{"t":"게임 점수를 보여 주려고","mis":"K2-1-u6-X02"}],"explanation":["안내판은 그곳을 이용하는 방법과 주의할 점을 알려 줘요.","생일이나 게임 점수는 안내판이 알려 주는 내용이 아니에요.","매체마다 알려 주는 것이 달라요."],"variant_rule":{"alt":[{"stem":"광고를 만드는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람들에게 전하고 싶은 말을 알리려고","correct":true},{"t":"인물의 긴 이야기를 들려주려고","mis":"K2-1-u6-X02"},{"t":"놀이 기구 타는 차례를 정하려고","mis":"K2-1-u6-X02"}],"explanation":["광고는 사람들에게 전하고 싶은 말을 알려요.","인물의 이야기는 이야기책이 들려줘요.","매체마다 알려 주는 것이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#5','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"안내판","r":"이용 방법과 주의할 점"},{"l":"광고","r":"전하고 싶은 말"},{"l":"이야기책","r":"인물의 이야기"}],"mis":"K2-1-u6-X02","explanation":["안내판은 이용 방법과 주의할 점을 알려 줘요.","광고는 전하고 싶은 말을 알려요.","이야기책은 인물의 이야기를 들려줘요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"식단표","r":"오늘 먹을 음식"},{"l":"일기 예보","r":"내일의 날씨"},{"l":"알림장","r":"준비물과 숙제"}],"explanation":["식단표는 오늘 먹을 음식을 알려 줘요.","일기 예보는 날씨를 알려 줘요.","알림장은 준비물과 숙제를 알려 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#6','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',2,'mc','auto','안내판을 읽고 답해 보세요. 그네와 관련하여 지킬 일은 무엇인가요?',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":6,"concept":"K2-1-u6-C1","difficulty":2,"kind":"mc","stem":"안내판을 읽고 답해 보세요. 그네와 관련하여 지킬 일은 무엇인가요?","options":[{"t":"그네가 움직일 때 그네 앞으로 지나가지 않아요","correct":true},{"t":"그네는 서서 타요","mis":"K2-1-u6-X07"},{"t":"그네는 차례 없이 먼저 타요","mis":"K2-1-u6-X07"}],"explanation":["안내판 2번에 그네 앞으로 지나가지 않는다고 했어요.","서서 타거나 차례 없이 타라는 말은 안내판에 없어요.","안내판에서 그 줄을 찾아 짚어요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"},"variant_rule":{"alt":[{"stem":"광고를 읽고 답해 보세요. 책갈피를 받으려면 어떻게 해야 하나요?","options":[{"t":"책을 세 권 읽고 와요","correct":true},{"t":"도서관 청소를 해요","mis":"K2-1-u6-X07"},{"t":"책을 한 권 사 와요","mis":"K2-1-u6-X07"}],"explanation":["광고에 책을 세 권 읽고 오면 책갈피를 준다고 했어요.","청소나 책을 사 오라는 말은 광고에 없어요.","광고에서 그 줄을 찾아 짚어요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#7','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C2',2,'blank','auto','안내판을 보고 생각을 말했어요. 「나는 이 안내판이 꼭 필요하다고 생각해. (     ) 놀이터에서 다치지 않게 도와주거든.」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u6-X10']::text[],true,'{"seq":7,"concept":"K2-1-u6-C2","difficulty":2,"kind":"blank","stem":"안내판을 보고 생각을 말했어요. 「나는 이 안내판이 꼭 필요하다고 생각해. (     ) 놀이터에서 다치지 않게 도와주거든.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그런데","mis":"K2-1-u6-X10"},{"t":"그리고 나서","mis":"K2-1-u6-X10"}],"explanation":["까닭을 말할 때는 「왜냐하면 ~거든」을 써요.","「그런데」·「그리고 나서」는 까닭을 이끄는 말이 아니에요.","생각 뒤에 까닭을 이어 말해요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"},"variant_rule":{"alt":[{"stem":"광고를 보고 생각을 말했어요. 「나는 도서관에 가 보고 싶어. (     ) 책갈피를 받고 싶거든.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그래서 마침내","mis":"K2-1-u6-X10"},{"t":"그런데","mis":"K2-1-u6-X10"}],"explanation":["까닭을 말할 때는 「왜냐하면 ~거든」을 써요.","「그래서 마침내」·「그런데」는 까닭을 이끄는 말이 아니에요.","생각 뒤에 까닭을 이어 말해요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#8','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C2',2,'mc','auto','안내판을 보고 든 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X03']::text[],true,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":2,"kind":"mc","stem":"안내판을 보고 든 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"「차례대로 타면 안 다치니까 꼭 지켜야겠어.」","correct":true},{"t":"「그냥 지켜야겠어.」","mis":"K2-1-u6-X10"},{"t":"「안내판이 네모 모양이야.」","mis":"K2-1-u6-X03"}],"explanation":["「차례대로 타면 안 다치니까」가 까닭이에요.","「그냥」은 까닭이 드러나지 않아요.","안내판 모양은 보고 든 생각이 아니에요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"},"variant_rule":{"alt":[{"stem":"광고를 보고 든 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"「책을 읽으면 책갈피도 받으니까 가 보고 싶어.」","correct":true},{"t":"「그냥 가 보고 싶어.」","mis":"K2-1-u6-X10"},{"t":"「광고 글씨가 파란색이야.」","mis":"K2-1-u6-X03"}],"explanation":["「책갈피도 받으니까」가 까닭이에요.","「그냥」은 까닭이 드러나지 않아요.","글씨 색깔은 보고 든 생각이 아니에요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#9','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',2,'mc','auto','매체에서 중요한 내용을 찾으면 좋은 점은 무엇인가요?',ARRAY['K2-1-u6-X03']::text[],true,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"mc","stem":"매체에서 중요한 내용을 찾으면 좋은 점은 무엇인가요?","options":[{"t":"알아야 할 정보를 빠르고 정확하게 알 수 있어요","correct":true},{"t":"글자 수를 셀 수 있어요","mis":"K2-1-u6-X03"},{"t":"그림 색깔을 외울 수 있어요","mis":"K2-1-u6-X03"}],"explanation":["중요한 내용을 찾으면 꼭 알아야 할 정보를 알 수 있어요.","글자 수나 그림 색깔은 중요한 내용이 아니에요.","무엇을 알려 주려는지 생각해요."],"variant_rule":{"alt":[{"stem":"매체를 볼 때 먼저 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 알려 주려는지","correct":true},{"t":"종이가 얼마나 두꺼운지","mis":"K2-1-u6-X03"},{"t":"글씨가 몇 줄인지","mis":"K2-1-u6-X03"}],"explanation":["매체가 무엇을 알려 주려는지 생각하면 중요한 내용이 보여요.","종이 두께나 줄 수는 중요한 내용이 아니에요.","무엇을 알려 주려는지 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#10','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',3,'error','auto','정보를 주고받는 매체를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X01','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C1","difficulty":3,"kind":"error","stem":"정보를 주고받는 매체를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「연필도 매체야. 글씨를 쓸 수 있으니까.」","correct":true,"mis_target":"K2-1-u6-X01"},{"t":"하준 — 「책은 매체야.」","mis":"K2-1-u6-X16"},{"t":"다은 — 「일기 예보는 매체야.」","mis":"K2-1-u6-X16"}],"explanation":["연필은 글씨를 쓰는 도구일 뿐 정보를 알려 주지 않아요.","책과 일기 예보는 정보를 알려 주는 매체예요.","「무엇을 알려 주지?」 물어 대답이 나오는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 정보를 주고받는 매체를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「가방도 매체야. 책을 넣을 수 있으니까.」","correct":true,"mis_target":"K2-1-u6-X01"},{"t":"로아 — 「안내판은 매체야.」","mis":"K2-1-u6-X16"},{"t":"시우 — 「광고는 매체야.」","mis":"K2-1-u6-X16"}],"explanation":["가방은 물건을 담는 도구일 뿐 정보를 알려 주지 않아요.","안내판과 광고는 정보를 알려 주는 매체예요.","「무엇을 알려 주지?」 물어 대답이 나오는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#1','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',2,'mc','auto','광고를 읽고 답해 보세요. 이 광고에서 가장 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X03']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":2,"kind":"mc","stem":"광고를 읽고 답해 보세요. 이 광고에서 가장 중요한 내용은 무엇인가요?","options":[{"t":"도서관에서 책 잔치가 열리니 오라는 것","correct":true},{"t":"책갈피가 예쁘다는 것","mis":"K2-1-u6-X06"},{"t":"가을이 왔다는 것","mis":"K2-1-u6-X03"}],"explanation":["광고는 도서관 책 잔치에 오라고 알리는 것이 가장 중요해요.","책갈피는 책 잔치에 덧붙인 내용이에요.","「가을」은 때를 말한 것일 뿐이에요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#2','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',2,'mc','auto','다음 가운데 매체가 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":2,"concept":"K2-1-u6-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 매체가 아닌 것은 어느 것인가요?","options":[{"t":"줄넘기 줄","correct":true},{"t":"알림장","mis":"K2-1-u6-X16"},{"t":"표지판","mis":"K2-1-u6-X16"}],"explanation":["줄넘기 줄은 운동하는 도구일 뿐 정보를 알려 주지 않아요.","알림장과 표지판은 정보를 알려 주는 매체예요.","물음의 「아닌」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#3','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',3,'mc','auto','안내판을 읽고 답해 보세요. 이 안내판이 세워진 곳으로 가장 알맞은 곳은 어디인가요?',ARRAY['K2-1-u6-X04','K2-1-u6-X07']::text[],false,'{"seq":3,"concept":"K2-1-u6-C1","difficulty":3,"kind":"mc","stem":"안내판을 읽고 답해 보세요. 이 안내판이 세워진 곳으로 가장 알맞은 곳은 어디인가요?","options":[{"t":"놀이터 입구","correct":true},{"t":"도서관 책상 위","mis":"K2-1-u6-X04"},{"t":"수영장 탈의실","mis":"K2-1-u6-X07"}],"explanation":["미끄럼틀과 그네를 이용할 때 지킬 일이니 놀이터 입구가 알맞아요.","도서관이나 수영장과 관련된 내용은 없어요.","안내판의 제목과 내용을 함께 살펴요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#4','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',3,'error','auto','안내판을 보고 생각을 말했어요. 까닭을 들어 말하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X16']::text[],false,'{"seq":4,"concept":"K2-1-u6-C2","difficulty":3,"kind":"error","stem":"안내판을 보고 생각을 말했어요. 까닭을 들어 말하지 않은 친구는 누구인가요?","options":[{"t":"민지 — 「안내판이 좋아. 그냥 좋아.」","correct":true,"mis_target":"K2-1-u6-X10"},{"t":"준우 — 「쓰레기를 넣으라는 말이 좋아. 놀이터가 깨끗해지니까.」","mis":"K2-1-u6-X16"},{"t":"서윤 — 「그네 조심 줄이 필요해. 부딪히면 다치거든.」","mis":"K2-1-u6-X16"}],"explanation":["「그냥 좋아.」에는 까닭이 없어요.","준우와 서윤이는 까닭을 들어 말했어요.","「왜냐하면 ~거든」을 붙여 말해요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#5','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',3,'ox','auto','광고는 이야기책처럼 인물이 겪은 일을 길게 들려주는 매체예요.',ARRAY['K2-1-u6-X02']::text[],false,'{"seq":5,"concept":"K2-1-u6-C1","difficulty":3,"kind":"ox","stem":"광고는 이야기책처럼 인물이 겪은 일을 길게 들려주는 매체예요.","answer":"X","reason_options":[{"t":"광고는 전하고 싶은 말을 짧게 알리는 매체니까","correct":true},{"t":"광고와 이야기책은 알려 주는 내용이 같으니까","mis":"K2-1-u6-X02"}],"mis":"K2-1-u6-X02","explanation":["광고는 사람들에게 알리고 싶은 말을 짧게 전해요.","인물이 겪은 일은 이야기책이 들려줘요.","매체마다 알려 주는 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#6','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',3,'mc','auto','광고를 보고 「한 달 동안 누구나 올 수 있다니 좋다.」라고 생각했어요. 그렇게 생각한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":6,"concept":"K2-1-u6-C2","difficulty":3,"kind":"mc","stem":"광고를 보고 「한 달 동안 누구나 올 수 있다니 좋다.」라고 생각했어요. 그렇게 생각한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"바쁜 날이 있어도 다른 날 갈 수 있으니까","correct":true},{"t":"도서관이 멀리 있으니까","mis":"K2-1-u6-X09"},{"t":"광고 글씨가 크니까","mis":"K2-1-u6-X09"}],"explanation":["한 달 동안 열리면 편한 날을 골라 갈 수 있어요.","도서관이 멀다는 것은 좋다는 생각의 까닭이 되지 않아요.","글씨 크기는 이 생각과 상관없어요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#7','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',3,'mc','auto','학교 급식실 앞에 붙은 「식단표」를 보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X02']::text[],false,'{"seq":7,"concept":"K2-1-u6-C1","difficulty":3,"kind":"mc","stem":"학교 급식실 앞에 붙은 「식단표」를 보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"오늘 먹을 음식을 알려고","correct":true},{"t":"급식실 문 색깔을 알려고","mis":"K2-1-u6-X03"},{"t":"친구 이름을 외우려고","mis":"K2-1-u6-X02"}],"explanation":["식단표는 먹을 음식을 알려 주는 매체예요.","문 색깔은 식단표와 상관없어요.","친구 이름은 식단표가 알려 주는 내용이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#8','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',4,'mc','auto','안내판을 보고 생각을 가장 잘 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X11','K2-1-u6-X09']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":4,"kind":"mc","stem":"안내판을 보고 생각을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"「나는 3번이 가장 중요하다고 생각해. 왜냐하면 쓰레기가 없어야 모두가 깨끗한 놀이터에서 놀 수 있거든.」","correct":true},{"t":"「나는 3번이 가장 중요해. 무조건이야!」","mis":"K2-1-u6-X11"},{"t":"「나는 3번이 가장 중요해. 왜냐하면 오늘 비가 오거든.」","mis":"K2-1-u6-X09"}],"explanation":["생각과 그에 맞는 까닭을 예의 바르게 말했어요.","「무조건이야!」는 우기는 말이에요.","비가 오는 것은 이 생각의 까닭이 되지 않아요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#9','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',4,'essay','teacher','학교나 동네에서 본 안내판이나 광고를 하나 떠올려, 무엇을 알려 주었는지 쓰고 그것을 보고 든 생각을 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C2","difficulty":4,"kind":"essay","stem":"학교나 동네에서 본 안내판이나 광고를 하나 떠올려, 무엇을 알려 주었는지 쓰고 그것을 보고 든 생각을 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 복도에 「뛰지 말고 걸어요」 안내판이 있어요. 복도에서 지킬 일을 알려 줘요. 나는 이 안내판이 꼭 필요하다고 생각해요. 왜냐하면 복도에서 뛰면 부딪혀 다칠 수 있기 때문이에요.","scoring_points":["어떤 매체를 보았는지 썼는가","그 매체가 알려 준 중요한 내용을 썼는가","보고 든 생각을 까닭과 함께 썼는가"]},"explanation":["어떤 매체인지.","중요한 내용.","생각과 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#10','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',4,'essay','teacher','안내판을 읽고 이 안내판에 꼭 더 넣으면 좋을 지킬 일을 하나 써 보고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C1","difficulty":4,"kind":"essay","stem":"안내판을 읽고 이 안내판에 꼭 더 넣으면 좋을 지킬 일을 하나 써 보고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 「4. 놀이 기구에서 친구를 밀지 않아요.」를 넣고 싶어요. 왜냐하면 밀면 떨어져서 크게 다칠 수 있기 때문이에요.","scoring_points":["놀이터에서 지킬 일을 알맞게 썼는가","안내판에 이미 있는 내용과 겹치지 않는가","그렇게 생각한 까닭을 썼는가"]},"explanation":["알맞은 지킬 일.","겹치지 않기.","까닭."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#1','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],true,'{"seq":1,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"줄넘기를 하면 좋은 점","correct":true},{"t":"줄넘기 줄의 색깔","mis":"K2-1-u6-X03"},{"t":"운동장의 크기","mis":"K2-1-u6-X04"}],"explanation":["제목이 「줄넘기의 좋은 점」이니 줄넘기의 좋은 점을 알려 주는 글이에요.","줄 색깔은 글에 나오지 않아요.","운동장은 줄넘기를 할 수 있는 곳의 예일 뿐이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"손을 깨끗이 씻는 일","correct":true},{"t":"비누의 냄새","mis":"K2-1-u6-X03"},{"t":"감기에 걸린 친구 이름","mis":"K2-1-u6-X04"}],"explanation":["제목이 「손을 깨끗이 씻어요」이니 손 씻기를 알려 주는 글이에요.","비누 냄새는 글에 나오지 않아요.","친구 이름은 글에 없어요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#2','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],true,'{"seq":2,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"줄넘기","correct":true},{"t":"마당","mis":"K2-1-u6-X05"},{"t":"다리","mis":"K2-1-u6-X05"}],"explanation":["「줄넘기」가 문단마다 여러 번 나와요.","「마당」과 「다리」는 한 번씩만 나와요.","자주 나오는 낱말이 중요한 낱말이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"손","correct":true},{"t":"감기","mis":"K2-1-u6-X05"},{"t":"거품","mis":"K2-1-u6-X05"}],"explanation":["「손」이 글 곳곳에 여러 번 나와요.","「감기」와 「거품」은 한 번씩만 나와요.","자주 나오는 낱말이 중요한 낱말이에요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#3','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C3',1,'ox','auto','제목에는 글에서 가장 중요한 내용이 담겨 있는 경우가 많아요.',ARRAY['K2-1-u6-X04']::text[],true,'{"seq":3,"concept":"K2-1-u6-C3","difficulty":1,"kind":"ox","stem":"제목에는 글에서 가장 중요한 내용이 담겨 있는 경우가 많아요.","answer":"O","reason_options":[{"t":"제목을 보면 글이 무엇을 알려 줄지 알 수 있으니까","correct":true},{"t":"제목은 글과 상관없이 아무렇게나 붙이니까","mis":"K2-1-u6-X04"}],"mis":"K2-1-u6-X04","explanation":["제목은 글 전체의 중요한 내용을 알려 줘요.","그래서 글을 읽기 전에 제목부터 살펴요.","제목을 소리 내어 읽어 봐요."],"variant_rule":{"alt":[{"stem":"글에 한 번만 나오는 낱말이 그 글에서 가장 중요한 낱말이에요.","answer":"X","reason_options":[{"t":"여러 번 나오고 제목과 관련 있는 낱말이 중요한 낱말이니까","correct":true},{"t":"한 번만 나와야 눈에 잘 띄니까","mis":"K2-1-u6-X05"}],"explanation":["중요한 낱말은 글에 여러 번 나와요.","한 번만 나오는 낱말은 덧붙인 것일 때가 많아요.","나올 때마다 세어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#4','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',1,'mc','auto','각 부분에서 가장 중요한 문장을 무엇이라고 하나요?',ARRAY['K2-1-u6-X06']::text[],true,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"각 부분에서 가장 중요한 문장을 무엇이라고 하나요?","options":[{"t":"중심 문장","correct":true},{"t":"끝 문장","mis":"K2-1-u6-X06"},{"t":"긴 문장","mis":"K2-1-u6-X06"}],"explanation":["각 부분에서 가장 중요한 문장을 중심 문장이라고 해요.","끝에 있거나 길다고 중심 문장인 것은 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"variant_rule":{"alt":[{"stem":"글에서 중요한 내용을 찾는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글자 수 세기","correct":true},{"t":"제목 살펴보기","mis":"K2-1-u6-X16"},{"t":"중심 문장 찾기","mis":"K2-1-u6-X16"}],"explanation":["글자 수를 센다고 중요한 내용을 알 수는 없어요.","제목 살펴보기와 중심 문장 찾기는 알맞은 방법이에요.","물음의 「않은」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#5','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],true,'{"seq":5,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기를 하면 몸이 튼튼해집니다.","correct":true},{"t":"팔과 다리를 함께 움직이기 때문입니다.","mis":"K2-1-u6-X06"},{"t":"줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다.","mis":"K2-1-u6-X07"}],"explanation":["첫째 부분에서 가장 하고 싶은 말은 「몸이 튼튼해진다」예요.","「~때문입니다」는 까닭을 덧붙인 문장이에요.","「줄 하나만 있으면」은 셋째 부분의 문장이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"손을 깨끗이 씻으면 감기를 막을 수 있습니다.","correct":true},{"t":"손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","mis":"K2-1-u6-X06"},{"t":"손바닥과 손등, 손가락 사이까지 문지릅니다.","mis":"K2-1-u6-X07"}],"explanation":["첫째 부분에서 가장 하고 싶은 말은 「감기를 막을 수 있다」예요.","「~때문입니다」는 까닭을 덧붙인 문장이에요.","「손가락 사이까지」는 둘째 부분의 문장이에요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#6','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',2,'match','auto','글을 읽고 각 부분과 중요한 내용을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K2-1-u6-C5","difficulty":2,"kind":"match","stem":"글을 읽고 각 부분과 중요한 내용을 알맞게 이어 보세요.","pairs":[{"l":"첫째 부분","r":"몸이 튼튼해진다"},{"l":"둘째 부분","r":"친구와 즐겁게 할 수 있다"},{"l":"셋째 부분","r":"어디서나 할 수 있다"}],"mis":"K2-1-u6-X06","explanation":["첫째 부분은 몸이 튼튼해진다는 내용이에요.","둘째 부분은 친구와 즐겁게 할 수 있다는 내용이에요.","셋째 부분은 어디서나 할 수 있다는 내용이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 각 부분과 중요한 내용을 알맞게 이어 보세요.","pairs":[{"l":"첫째 부분","r":"손을 씻으면 감기를 막는다"},{"l":"둘째 부분","r":"비누로 구석구석 씻는다"},{"l":"셋째 부분","r":"씻어야 할 때가 있다"}],"explanation":["첫째 부분은 감기를 막는다는 내용이에요.","둘째 부분은 씻는 방법이에요.","셋째 부분은 꼭 씻어야 할 때예요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#7','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C4',2,'mc','auto','글을 읽고 답해 보세요. 이 글의 중요한 낱말을 바르게 모은 것은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],true,'{"seq":7,"concept":"K2-1-u6-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글의 중요한 낱말을 바르게 모은 것은 어느 것인가요?","options":[{"t":"줄넘기 · 좋은 점","correct":true},{"t":"줄넘기 · 마당","mis":"K2-1-u6-X05"},{"t":"운동장 · 마당","mis":"K2-1-u6-X05"}],"explanation":["「줄넘기」는 자주 나오고, 「좋은 점」은 제목에 있어요.","「마당」과 「운동장」은 한 번씩만 나온 예예요.","자주 나오고 제목과 관련 있는 낱말을 골라요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 이 글의 중요한 낱말을 바르게 모은 것은 어느 것인가요?","options":[{"t":"손 · 씻기","correct":true},{"t":"손 · 거품","mis":"K2-1-u6-X05"},{"t":"균 · 밥","mis":"K2-1-u6-X05"}],"explanation":["「손」과 「씻다」가 글에 여러 번 나오고 제목에도 있어요.","「거품」·「균」·「밥」은 한 번씩만 나와요.","자주 나오고 제목과 관련 있는 낱말을 골라요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#8','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C4',2,'sa','auto','「토끼는 귀가 깁니다. 토끼는 풀을 좋아합니다. 토끼는 깡충깡충 뜁니다.」 이 글에 자주 나오는 낱말을 두 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u6-C4","difficulty":2,"kind":"sa","stem":"「토끼는 귀가 깁니다. 토끼는 풀을 좋아합니다. 토끼는 깡충깡충 뜁니다.」 이 글에 자주 나오는 낱말을 두 글자로 써 보세요.","answer":["토끼"],"explanation":["「토끼」가 세 문장에 모두 나와요.","자주 나오는 낱말이 중요한 낱말이에요.","이 글은 토끼에 대해 알려 주는 글이에요."],"variant_rule":{"alt":[{"stem":"「기린은 목이 깁니다. 기린은 나뭇잎을 먹습니다. 기린은 키가 큽니다.」 이 글에 자주 나오는 낱말을 두 글자로 써 보세요.","answer":["기린"],"explanation":["「기린」이 세 문장에 모두 나와요.","자주 나오는 낱말이 중요한 낱말이에요.","이 글은 기린에 대해 알려 주는 글이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#9','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',2,'mc','auto','중심 문장을 찾을 때 생각하면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X03']::text[],true,'{"seq":9,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"중심 문장을 찾을 때 생각하면 좋은 것은 어느 것인가요?","options":[{"t":"이 부분에서 가장 하고 싶은 말이 무엇인지","correct":true},{"t":"어느 문장이 가장 긴지","mis":"K2-1-u6-X06"},{"t":"어느 문장에 그림이 있는지","mis":"K2-1-u6-X03"}],"explanation":["그 부분에서 가장 하고 싶은 말이 중심 문장이에요.","길다고 중심 문장은 아니에요.","그림이 있는지는 상관없어요."],"variant_rule":{"alt":[{"stem":"「~때문입니다」로 끝나는 문장은 주로 어떤 문장인가요?","options":[{"t":"앞 문장의 까닭을 덧붙인 문장","correct":true},{"t":"그 부분의 중심 문장","mis":"K2-1-u6-X06"},{"t":"글의 제목","mis":"K2-1-u6-X04"}],"explanation":["「~때문입니다」는 까닭을 덧붙일 때 써요.","중심 문장을 뒷받침하는 문장이에요.","제목은 글 맨 위에 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#10','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"도윤 — 「줄넘기는 마당에서만 할 수 있다.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"하린 — 「줄넘기를 하면 몸이 튼튼해진다.」","mis":"K2-1-u6-X16"},{"t":"지후 — 「줄넘기는 친구와 즐겁게 할 수 있다.」","mis":"K2-1-u6-X16"}],"explanation":["글에는 줄넘기를 어디서나 할 수 있다고 했어요.","「마당에서만」은 글의 내용과 달라요.","하린이와 지후는 바르게 정리했어요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"예린 — 「손은 밥을 먹은 뒤에만 씻으면 된다.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"민호 — 「손을 씻으면 감기를 막을 수 있다.」","mis":"K2-1-u6-X16"},{"t":"서아 — 「비누로 거품을 내어 구석구석 씻는다.」","mis":"K2-1-u6-X16"}],"explanation":["글에는 밥을 먹기 전과 밖에서 돌아왔을 때 씻는다고 했어요.","「밥을 먹은 뒤에만」은 글과 달라요.","민호와 서아는 바르게 정리했어요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#1','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 셋째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":1,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 셋째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다.","correct":true},{"t":"운동장에서도, 집 앞 마당에서도 할 수 있습니다.","mis":"K2-1-u6-X06"},{"t":"긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","mis":"K2-1-u6-X07"}],"explanation":["셋째 부분에서 가장 하고 싶은 말은 「어디서나 할 수 있다」예요.","「운동장에서도, 마당에서도」는 예를 든 문장이에요.","「긴 줄」은 둘째 부분의 문장이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#2','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C4',2,'mc','auto','글을 읽고 답해 보세요. 자주 나오는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":2,"concept":"K2-1-u6-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 자주 나오는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"마당","correct":true},{"t":"줄넘기","mis":"K2-1-u6-X16"},{"t":"할 수 있습니다","mis":"K2-1-u6-X16"}],"explanation":["「마당」은 한 번만 나와요.","「줄넘기」와 「할 수 있습니다」는 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#3','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C3',3,'mc','auto','「꿀벌은 꽃에서 꿀을 모읍니다. 꽃가루를 옮겨 열매가 열리도록 돕습니다. 힘을 모아 벌집을 짓습니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":3,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「꿀벌은 꽃에서 꿀을 모읍니다. 꽃가루를 옮겨 열매가 열리도록 돕습니다. 힘을 모아 벌집을 짓습니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"꿀벌이 하는 일","correct":true},{"t":"꽃의 색깔","mis":"K2-1-u6-X04"},{"t":"맛있는 꿀 요리","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 꿀벌이 하는 일을 알려 줘요.","꽃 색깔은 글에 나오지 않아요.","꿀 요리는 글과 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#4','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',3,'error','auto','글의 중심 문장을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X16']::text[],false,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글의 중심 문장을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"소율 — 「둘째 부분: 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.」","correct":true,"mis_target":"K2-1-u6-X06"},{"t":"시우 — 「첫째 부분: 줄넘기를 하면 몸이 튼튼해집니다.」","mis":"K2-1-u6-X16"},{"t":"아린 — 「셋째 부분: 줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다.」","mis":"K2-1-u6-X16"}],"explanation":["둘째 부분의 중심 문장은 「줄넘기는 친구와 함께 즐겁게 할 수 있습니다.」예요.","「긴 줄을 여럿이 함께 넘으면」은 예를 든 문장이에요.","시우와 아린이는 바르게 찾았어요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#5','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',3,'ox','auto','글을 읽고 답해 보세요. 「팔과 다리를 함께 움직이기 때문입니다.」는 이 글 전체의 중요한 내용이에요.',ARRAY['K2-1-u6-X06']::text[],false,'{"seq":5,"concept":"K2-1-u6-C5","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 「팔과 다리를 함께 움직이기 때문입니다.」는 이 글 전체의 중요한 내용이에요.","answer":"X","reason_options":[{"t":"첫째 부분에서 까닭을 덧붙인 문장일 뿐이니까","correct":true},{"t":"글에 나온 문장은 모두 글 전체의 중요한 내용이니까","mis":"K2-1-u6-X06"}],"mis":"K2-1-u6-X06","explanation":["이 문장은 몸이 튼튼해지는 까닭을 덧붙였어요.","글 전체의 중요한 내용은 「줄넘기의 좋은 점」이에요.","중심 문장과 덧붙인 문장을 가려요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#6','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C3',3,'mc','auto','제목이 「겨울잠을 자는 동물」인 글에 나올 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":6,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"제목이 「겨울잠을 자는 동물」인 글에 나올 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"곰과 개구리가 겨울에 잠을 자는 까닭","correct":true},{"t":"여름 바닷가에서 노는 방법","mis":"K2-1-u6-X04"},{"t":"눈사람 만드는 방법","mis":"K2-1-u6-X04"}],"explanation":["제목을 보면 겨울잠을 자는 동물 이야기가 나올 거예요.","여름 바닷가는 제목과 맞지 않아요.","눈사람은 겨울과 관련 있지만 동물 이야기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#7','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C4',3,'mc','auto','「사과는 빨갛습니다. 사과는 새콤달콤합니다. 아침에 먹는 사과는 몸에 좋습니다.」 이 글에서 중요한 낱말과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":7,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"「사과는 빨갛습니다. 사과는 새콤달콤합니다. 아침에 먹는 사과는 몸에 좋습니다.」 이 글에서 중요한 낱말과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「사과」 — 세 문장에 모두 나오니까","correct":true},{"t":"「아침」 — 마지막 문장에 나오니까","mis":"K2-1-u6-X05"},{"t":"「빨갛다」 — 맨 처음에 나오니까","mis":"K2-1-u6-X05"}],"explanation":["「사과」가 세 문장에 모두 나와요.","「아침」과 「빨갛다」는 한 번씩만 나와요.","처음에 나온다고 중요한 낱말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#8','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',4,'mc','auto','글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['K2-1-u6-X06']::text[],false,'{"seq":8,"concept":"K2-1-u6-C5","difficulty":4,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"줄넘기를 하면 몸이 튼튼해지고, 친구와 즐겁게 할 수 있으며, 어디서나 할 수 있다.","correct":true},{"t":"줄넘기를 하면 몸이 튼튼해진다.","mis":"K2-1-u6-X06"},{"t":"줄넘기는 운동장과 마당에서 할 수 있다.","mis":"K2-1-u6-X06"}],"explanation":["세 부분의 중심 문장을 모두 모아 정리했어요.","한 부분의 내용만으로는 글 전체를 정리할 수 없어요.","운동장과 마당은 예를 든 내용이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#9','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 세 부분의 중심 문장을 찾아 쓰고, 그것을 모아 이 글의 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 세 부분의 중심 문장을 찾아 쓰고, 그것을 모아 이 글의 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 첫째 — 손을 깨끗이 씻으면 감기를 막을 수 있다. 둘째 — 비누로 거품을 내어 구석구석 씻는다. 셋째 — 밖에서 돌아왔을 때와 밥 먹기 전에 꼭 씻는다. 정리: 손을 깨끗이 씻으면 감기를 막을 수 있으니, 비누로 구석구석 씻고 씻어야 할 때를 꼭 지키자.","scoring_points":["세 부분의 중심 문장을 찾아 썼는가","까닭이나 예를 든 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["세 중심 문장.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#10','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C4',4,'essay','teacher','좋아하는 동물이나 물건 하나를 골라, 그 낱말이 자주 나오도록 세 문장의 짧은 글을 쓰고 알맞은 제목을 붙여 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C4","difficulty":4,"kind":"essay","stem":"좋아하는 동물이나 물건 하나를 골라, 그 낱말이 자주 나오도록 세 문장의 짧은 글을 쓰고 알맞은 제목을 붙여 보세요.","answer_guide":{"answer":"예: 제목 — 우리 집 고양이. 우리 집 고양이는 털이 부드러워요. 고양이는 햇볕 아래에서 잠을 자요. 고양이는 공을 굴리며 놀아요.","scoring_points":["하나의 대상에 대해 세 문장을 썼는가","그 대상을 나타내는 낱말이 자주 나오는가","글 내용에 어울리는 제목을 붙였는가"]},"explanation":["세 문장.","자주 나오는 낱말.","어울리는 제목."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#1','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],true,'{"seq":1,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 내용은 무엇인가요?","options":[{"t":"꿀벌이 하는 일","correct":true},{"t":"꿀벌의 색깔","mis":"K2-1-u6-X03"},{"t":"꽃집에서 꽃 사는 법","mis":"K2-1-u6-X04"}],"explanation":["제목이 「꿀벌이 하는 일」이니 꿀벌이 하는 일을 알려 줄 거예요.","꿀벌 색깔은 글에 나오지 않아요.","꽃집 이야기는 제목과 맞지 않아요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 내용은 무엇인가요?","options":[{"t":"물을 아껴 쓰는 방법","correct":true},{"t":"수영을 잘하는 방법","mis":"K2-1-u6-X04"},{"t":"물의 색깔","mis":"K2-1-u6-X03"}],"explanation":["제목이 「물을 아껴 써요」이니 물을 아끼는 방법을 알려 줄 거예요.","수영은 제목과 맞지 않아요.","물의 색깔은 글에 나오지 않아요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#2','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',1,'mc','auto','글을 읽고 답해 보세요. 꿀벌이 하는 일로 글에 나온 것은 어느 것인가요?',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":2,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 꿀벌이 하는 일로 글에 나온 것은 어느 것인가요?","options":[{"t":"꽃에서 꿀을 모은다","correct":true},{"t":"노래를 부른다","mis":"K2-1-u6-X07"},{"t":"잠만 잔다","mis":"K2-1-u6-X07"}],"explanation":["글에 꿀벌이 꽃에서 꿀을 모은다고 했어요.","노래를 부르거나 잠만 잔다는 말은 글에 없어요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 물을 아끼는 방법으로 글에 나온 것은 어느 것인가요?","options":[{"t":"이를 닦을 때 컵에 물을 받아 쓴다","correct":true},{"t":"목욕물을 가득 받아 놓는다","mis":"K2-1-u6-X07"},{"t":"물을 틀어 놓고 이를 닦는다","mis":"K2-1-u6-X07"}],"explanation":["글에 컵에 물을 받아 쓴다고 했어요.","물을 가득 받거나 틀어 놓는 것은 물을 낭비하는 일이에요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#3','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',1,'ox','auto','글을 읽고 답해 보세요. 꿀벌은 혼자서만 벌집을 짓는다고 했어요.',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":3,"concept":"K2-1-u6-C5","difficulty":1,"kind":"ox","stem":"글을 읽고 답해 보세요. 꿀벌은 혼자서만 벌집을 짓는다고 했어요.","answer":"X","reason_options":[{"t":"글에 여럿이 힘을 모아 벌집을 짓는다고 했으니까","correct":true},{"t":"꿀벌은 언제나 혼자 다니니까","mis":"K2-1-u6-X07"}],"mis":"K2-1-u6-X07","explanation":["글에 「여럿이 힘을 모아」 벌집을 짓는다고 했어요.","「혼자서만」은 글과 달라요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 비누칠을 하는 동안에는 수도꼭지를 잠근다고 했어요.","answer":"O","reason_options":[{"t":"글에 그렇게 쓰여 있으니까","correct":true},{"t":"물은 계속 틀어 두어야 하니까","mis":"K2-1-u6-X07"}],"explanation":["글에 비누칠하는 동안 수도꼭지를 잠근다고 했어요.","그렇게 하면 물을 아낄 수 있어요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#4','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],true,'{"seq":4,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"꿀벌","correct":true},{"t":"열매","mis":"K2-1-u6-X05"},{"t":"벌집","mis":"K2-1-u6-X05"}],"explanation":["「꿀벌」이 세 문장에 모두 나와요.","「열매」와 「벌집」은 한 번씩만 나와요.","자주 나오는 낱말이 중요한 낱말이에요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"물","correct":true},{"t":"컵","mis":"K2-1-u6-X05"},{"t":"샤워","mis":"K2-1-u6-X05"}],"explanation":["「물」이 여러 번 나와요.","「컵」과 「샤워」는 한 번씩만 나와요.","자주 나오는 낱말이 중요한 낱말이에요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#5','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',2,'match','auto','글을 읽고 글의 문장과 꿀벌이 하는 일을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C5","difficulty":2,"kind":"match","stem":"글을 읽고 글의 문장과 꿀벌이 하는 일을 알맞게 이어 보세요.","pairs":[{"l":"꽃에서 꿀을 모읍니다","r":"꿀 모으기"},{"l":"꽃가루를 옮겨 줍니다","r":"열매 맺기 돕기"},{"l":"힘을 모아 짓습니다","r":"벌집 짓기"}],"mis":"K2-1-u6-X07","explanation":["꿀을 모으는 일이에요.","꽃가루를 옮겨 열매가 열리게 도와요.","여럿이 힘을 모아 벌집을 지어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"글을 읽고 물을 쓰는 때와 아끼는 방법을 알맞게 이어 보세요.","pairs":[{"l":"이를 닦을 때","r":"컵에 물을 받아 쓴다"},{"l":"비누칠을 할 때","r":"수도꼭지를 잠근다"},{"l":"샤워를 할 때","r":"짧게 한다"}],"explanation":["이를 닦을 때는 컵을 써요.","비누칠할 때는 물을 잠가요.","샤워는 짧게 해요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#6','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],true,'{"seq":6,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"꿀벌은 꿀을 모으고, 꽃가루를 옮기고, 함께 벌집을 짓는다.","correct":true},{"t":"꿀벌은 꽃에서 꿀을 모은다.","mis":"K2-1-u6-X06"},{"t":"꿀벌은 꽃을 좋아한다.","mis":"K2-1-u6-X07"}],"explanation":["꿀벌이 하는 일 세 가지를 모두 모았어요.","한 가지만으로는 글 전체를 정리할 수 없어요.","「꽃을 좋아한다」는 글에 없는 내용이에요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"컵에 물을 받아 쓰고, 수도꼭지를 잠그고, 샤워를 짧게 해서 물을 아끼자.","correct":true},{"t":"샤워를 짧게 하자.","mis":"K2-1-u6-X06"},{"t":"물을 많이 마시자.","mis":"K2-1-u6-X07"}],"explanation":["물을 아끼는 방법 세 가지를 모두 모았어요.","한 가지만으로는 글 전체를 정리할 수 없어요.","물을 마시자는 말은 글에 없어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#7','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C3',2,'mc','auto','「강아지는 냄새를 잘 맡습니다. 강아지는 주인을 반기며 꼬리를 흔듭니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],true,'{"seq":7,"concept":"K2-1-u6-C3","difficulty":2,"kind":"mc","stem":"「강아지는 냄새를 잘 맡습니다. 강아지는 주인을 반기며 꼬리를 흔듭니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"강아지의 특징","correct":true},{"t":"고양이 기르는 법","mis":"K2-1-u6-X04"},{"t":"맛있는 간식","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 강아지에 대해 알려 줘요.","고양이는 글에 나오지 않아요.","간식은 글과 상관없어요."],"variant_rule":{"alt":[{"stem":"「해바라기는 해를 따라 고개를 돌립니다. 해바라기 씨는 먹을 수 있습니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"해바라기에 대해 알아봐요","correct":true},{"t":"장미꽃 키우기","mis":"K2-1-u6-X04"},{"t":"여름 방학 계획","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 해바라기에 대해 알려 줘요.","장미꽃은 글에 나오지 않아요.","방학 계획은 글과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#8','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',2,'sa','auto','글을 읽고 답해 보세요. 꿀벌은 무엇을 옮겨 열매가 열리도록 돕나요? 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u6-C5","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 꿀벌은 무엇을 옮겨 열매가 열리도록 돕나요? 세 글자로 써 보세요.","answer":["꽃가루"],"explanation":["글에 꿀벌이 꽃가루를 옮긴다고 했어요.","꽃가루가 옮겨져야 열매가 열려요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 이를 닦을 때 물을 받아 쓰라고 한 그릇은 무엇인가요? 한 글자로 써 보세요.","answer":["컵"],"explanation":["글에 컵에 물을 받아 쓴다고 했어요.","컵을 쓰면 물을 덜 쓰게 돼요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#9','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',2,'mc','auto','새로운 글을 읽고 중요한 내용을 찾는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X06']::text[],true,'{"seq":9,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"새로운 글을 읽고 중요한 내용을 찾는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"제목 살펴보기 → 자주 나오는 낱말 찾기 → 중심 문장 모아 정리하기","correct":true},{"t":"그림 색깔 보기 → 글자 수 세기 → 끝내기","mis":"K2-1-u6-X03"},{"t":"끝 문장만 읽기 → 끝내기","mis":"K2-1-u6-X06"}],"explanation":["제목, 자주 나오는 낱말, 중심 문장 차례로 살펴요.","그림 색깔이나 글자 수로는 중요한 내용을 알 수 없어요.","끝 문장만 읽으면 다른 부분을 놓쳐요."],"variant_rule":{"alt":[{"stem":"중요한 내용을 찾으며 글을 읽으면 좋은 점은 무엇인가요?","options":[{"t":"글이 알려 주는 핵심을 알고 새롭게 안 것을 나눌 수 있어요","correct":true},{"t":"글을 읽지 않아도 돼요","mis":"K2-1-u6-X07"},{"t":"글자를 빨리 쓸 수 있어요","mis":"K2-1-u6-X03"}],"explanation":["핵심을 알면 새롭게 안 것을 친구와 나눌 수 있어요.","글을 꼼꼼히 읽어야 중요한 내용을 찾아요.","글자 쓰기 빠르기와는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#10','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',3,'error','auto','글을 읽고 새롭게 안 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 새롭게 안 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"지안 — 「꿀벌은 꽃잎을 먹고 산대.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"하윤 — 「꿀벌이 꽃가루를 옮겨서 열매가 열린대.」","mis":"K2-1-u6-X16"},{"t":"준우 — 「꿀벌은 여럿이 함께 벌집을 짓는대.」","mis":"K2-1-u6-X16"}],"explanation":["꽃잎을 먹는다는 말은 글에 없어요.","글에 없는 내용을 있다고 하면 안 돼요.","하윤이와 준우는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 새롭게 안 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도담 — 「샤워는 오래 해야 물을 아낀대.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"서윤 — 「이를 닦을 때 컵을 쓰면 물을 아낀대.」","mis":"K2-1-u6-X16"},{"t":"현우 — 「비누칠할 때는 물을 잠가야 한대.」","mis":"K2-1-u6-X16"}],"explanation":["글에는 샤워를 짧게 한다고 했어요.","「오래」는 글과 반대예요.","서윤이와 현우는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#1','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 이 글의 첫 문장 「물을 아껴 쓰는 방법을 알아봅시다.」는 어떤 문장인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X03']::text[],false,'{"seq":1,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글의 첫 문장 「물을 아껴 쓰는 방법을 알아봅시다.」는 어떤 문장인가요?","options":[{"t":"글 전체가 무엇을 알려 줄지 밝힌 문장","correct":true},{"t":"이를 닦는 방법만 알려 주는 문장","mis":"K2-1-u6-X06"},{"t":"글과 상관없는 문장","mis":"K2-1-u6-X03"}],"explanation":["첫 문장이 물을 아끼는 방법을 알아보자고 밝혀요.","이를 닦는 방법은 그다음 문장의 내용이에요.","첫 문장은 글 전체와 관련 있어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#2','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 꿀벌이 하는 일이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":2,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 꿀벌이 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"꿀을 모아 사람에게 팔아요","correct":true},{"t":"벌집을 지어요","mis":"K2-1-u6-X16"},{"t":"꽃가루를 옮겨요","mis":"K2-1-u6-X16"}],"explanation":["꿀을 판다는 말은 글에 없어요.","벌집 짓기와 꽃가루 옮기기는 꿀벌이 하는 일이에요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#3','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C3',3,'mc','auto','글을 읽고 답해 보세요. 제목을 「꿀벌의 생김새」로 바꾼다면 어떤 점이 알맞지 않은가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":3,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 「꿀벌의 생김새」로 바꾼다면 어떤 점이 알맞지 않은가요?","options":[{"t":"글은 꿀벌의 생김새가 아니라 꿀벌이 하는 일을 알려 주니까","correct":true},{"t":"「꿀벌」이라는 낱말이 들어 있으니까","mis":"K2-1-u6-X04"},{"t":"제목이 짧아지니까","mis":"K2-1-u6-X04"}],"explanation":["글 내용은 꿀벌이 하는 일이에요.","제목은 글의 중요한 내용과 맞아야 해요.","낱말이 같거나 길이가 짧다고 알맞은 제목은 아니에요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#4','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 한 부분만 보고 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X16']::text[],false,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 한 부분만 보고 정리한 친구는 누구인가요?","options":[{"t":"민지 — 「이 글의 중요한 내용은 샤워를 짧게 하자는 것이다.」","correct":true,"mis_target":"K2-1-u6-X06"},{"t":"로아 — 「컵 쓰기, 수도꼭지 잠그기, 짧은 샤워로 물을 아끼자는 것이다.」","mis":"K2-1-u6-X16"},{"t":"태민 — 「여러 방법으로 물을 아껴 쓰자는 것이다.」","mis":"K2-1-u6-X16"}],"explanation":["샤워는 물을 아끼는 방법 가운데 하나일 뿐이에요.","글 전체의 중요한 내용은 물을 아끼는 여러 방법이에요.","로아와 태민이는 글 전체를 보고 정리했어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#5','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',3,'ox','auto','글을 읽고 답해 보세요. 「꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.」를 읽고 꿀벌이 없으면 열매가 잘 열리지 않을 수 있다는 것을 새롭게 알 수 있어요.',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":5,"concept":"K2-1-u6-C5","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 「꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.」를 읽고 꿀벌이 없으면 열매가 잘 열리지 않을 수 있다는 것을 새롭게 알 수 있어요.","answer":"O","reason_options":[{"t":"꿀벌이 꽃가루를 옮겨야 열매가 열린다고 했으니까","correct":true},{"t":"글에 꿀벌이 열매를 먹는다고 했으니까","mis":"K2-1-u6-X07"}],"mis":"K2-1-u6-X07","explanation":["꽃가루를 옮겨 열매가 열리도록 돕는다고 했어요.","그러니 꿀벌이 없으면 열매가 잘 열리지 않을 수 있어요.","꿀벌이 열매를 먹는다는 말은 글에 없어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#6','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":6,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"샤워","correct":true},{"t":"물","mis":"K2-1-u6-X16"},{"t":"아껴","mis":"K2-1-u6-X16"}],"explanation":["「샤워」는 한 번만 나와요.","「물」과 「아껴」는 제목에도 있고 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#7','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',3,'mc','auto','「우리 몸에는 뼈가 있습니다. 뼈는 몸을 받쳐 줍니다. 그래서 우리는 똑바로 설 수 있습니다.」 이 글의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06']::text[],false,'{"seq":7,"concept":"K2-1-u6-C5","difficulty":3,"kind":"mc","stem":"「우리 몸에는 뼈가 있습니다. 뼈는 몸을 받쳐 줍니다. 그래서 우리는 똑바로 설 수 있습니다.」 이 글의 중심 문장은 어느 것인가요?","options":[{"t":"뼈는 몸을 받쳐 줍니다.","correct":true},{"t":"그래서 우리는 똑바로 설 수 있습니다.","mis":"K2-1-u6-X06"},{"t":"우리 몸에는 뼈가 있습니다.","mis":"K2-1-u6-X06"}],"explanation":["뼈가 몸을 받쳐 준다는 것이 가장 하고 싶은 말이에요.","「그래서 ~」는 그 결과를 덧붙인 문장이에요.","뼈가 있다는 것은 이야기를 시작하는 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#8','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',4,'mc','auto','글을 읽고 새롭게 안 내용과 더 알고 싶은 것을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X03']::text[],false,'{"seq":8,"concept":"K2-1-u6-C5","difficulty":4,"kind":"mc","stem":"글을 읽고 새롭게 안 내용과 더 알고 싶은 것을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「꿀벌이 열매가 열리게 돕는다는 것을 알았어. 꿀벌이 하루에 꽃을 얼마나 많이 찾아다니는지 더 알고 싶어.」","correct":true},{"t":"「꿀벌은 노래를 잘 부른다는 것을 알았어.」","mis":"K2-1-u6-X07"},{"t":"「꿀벌은 무섭다. 더 알고 싶은 것은 없어.」","mis":"K2-1-u6-X03"}],"explanation":["글에서 안 내용과 그와 이어지는 궁금한 점을 말했어요.","노래를 부른다는 것은 글에 없어요.","「무섭다」는 새롭게 안 내용이 아니에요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#9','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중요한 내용을 한 문장으로 정리하고, 글을 읽고 내가 실천할 일을 한 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중요한 내용을 한 문장으로 정리하고, 글을 읽고 내가 실천할 일을 한 가지 써 보세요.","answer_guide":{"answer":"예: 정리 — 컵 쓰기, 수도꼭지 잠그기, 짧은 샤워로 물을 아껴 쓰자. 실천 — 오늘부터 이를 닦을 때 꼭 컵에 물을 받아 쓰겠어요.","scoring_points":["물을 아끼는 여러 방법을 모아 한 문장으로 정리했는가","글에 없는 내용을 넣지 않았는가","실천할 일을 구체적으로 썼는가"]},"explanation":["한 문장 정리.","글에 있는 내용만.","실천할 일."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#10','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C3',4,'essay','teacher','글을 읽고 답해 보세요. 이 글에 어울리는 새 제목을 하나 지어 쓰고, 그 제목이 알맞은 까닭을 글의 내용을 들어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C3","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글에 어울리는 새 제목을 하나 지어 쓰고, 그 제목이 알맞은 까닭을 글의 내용을 들어 써 보세요.","answer_guide":{"answer":"예: 「바쁜 꿀벌의 하루」 — 글에 꿀벌이 꿀을 모으고, 꽃가루를 옮기고, 벌집을 짓는 여러 가지 일이 나오기 때문이에요.","scoring_points":["글의 내용과 어울리는 제목을 지었는가","제목이 글 전체를 아우르는가","글의 내용을 들어 까닭을 썼는가"]},"explanation":["어울리는 제목.","글 전체 아우르기.","까닭."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#1','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 하린이가 기르고 싶어 하는 것은 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],true,'{"seq":1,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하린이가 기르고 싶어 하는 것은 무엇인가요?","options":[{"t":"강낭콩","correct":true},{"t":"물고기","mis":"K2-1-u6-X08"},{"t":"달팽이","mis":"K2-1-u6-X08"}],"explanation":["하린이는 「강낭콩을 기르자.」라고 했어요.","물고기는 도윤이, 달팽이는 지후의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 민호가 하고 싶어 하는 놀이는 무엇인가요?","options":[{"t":"줄넘기","correct":true},{"t":"피구","mis":"K2-1-u6-X08"},{"t":"숨바꼭질","mis":"K2-1-u6-X08"}],"explanation":["민호는 「줄넘기를 하자.」라고 했어요.","피구는 서아, 숨바꼭질은 예린이의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#2','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',1,'mc','auto','대화를 읽고 답해 보세요. 도윤이가 물고기를 기르자고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],true,'{"seq":2,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이가 물고기를 기르자고 한 까닭은 무엇인가요?","options":[{"t":"먹이만 잘 주면 되어서 돌보기 쉬우니까","correct":true},{"t":"자라는 모습을 날마다 볼 수 있으니까","mis":"K2-1-u6-X08"},{"t":"물고기 색깔이 파란색이니까","mis":"K2-1-u6-X09"}],"explanation":["도윤이는 물고기가 돌보기 쉽다고 했어요.","자라는 모습은 하린이가 말한 까닭이에요.","물고기 색깔은 대화에 나오지 않아요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 예린이가 숨바꼭질을 하자고 한 까닭은 무엇인가요?","options":[{"t":"규칙이 쉬워서 누구나 할 수 있으니까","correct":true},{"t":"모두가 함께 뛸 수 있으니까","mis":"K2-1-u6-X08"},{"t":"오늘은 화요일이니까","mis":"K2-1-u6-X09"}],"explanation":["예린이는 숨바꼭질의 규칙이 쉽다고 했어요.","모두가 함께 뛸 수 있다는 것은 서아가 말한 까닭이에요.","「화요일」은 까닭이 아니에요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#3','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C6',1,'ox','auto','인물의 생각은 인물이 한 말에서 찾을 수 있어요.',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"ox","stem":"인물의 생각은 인물이 한 말에서 찾을 수 있어요.","answer":"O","reason_options":[{"t":"인물이 무엇을 하자고 하는지 말에 드러나니까","correct":true},{"t":"인물의 생각은 이름에만 쓰여 있으니까","mis":"K2-1-u6-X07"}],"mis":"K2-1-u6-X07","explanation":["「~하자.」처럼 인물의 말에 생각이 들어 있어요.","이름만으로는 생각을 알 수 없어요.","인물의 말을 꼼꼼히 읽어요."],"variant_rule":{"alt":[{"stem":"인물의 생각을 찾을 때는 그 생각의 까닭도 함께 찾는 것이 좋아요.","answer":"O","reason_options":[{"t":"생각과 까닭은 한 쌍이니까","correct":true},{"t":"까닭은 찾지 않아도 생각만 알면 되니까","mis":"K2-1-u6-X10"}],"explanation":["생각과 까닭은 한 쌍으로 찾아요.","까닭을 알면 그 생각을 더 잘 이해해요.","「왜 그렇게 생각했지?」 물어봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#4','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',1,'mc','auto','인물의 생각에 대한 까닭을 찾을 때 살펴볼 곳은 어디인가요?',ARRAY['K2-1-u6-X01','K2-1-u6-X03']::text[],true,'{"seq":4,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"인물의 생각에 대한 까닭을 찾을 때 살펴볼 곳은 어디인가요?","options":[{"t":"생각 뒤에 나오는 좋은 점이나 옳은 점","correct":true},{"t":"인물의 이름","mis":"K2-1-u6-X01"},{"t":"글의 쪽수","mis":"K2-1-u6-X03"}],"explanation":["생각 뒤에 「~거든」·「~니까」로 나오는 말이 까닭이에요.","이름은 까닭이 아니에요.","쪽수는 글의 내용과 상관없어요."],"variant_rule":{"alt":[{"stem":"까닭을 말할 때 자주 쓰는 말끝은 어느 것인가요?","options":[{"t":"「~거든」, 「~니까」","correct":true},{"t":"「~하자」, 「~할래」","mis":"K2-1-u6-X09"},{"t":"「~안녕」, 「~잘 가」","mis":"K2-1-u6-X09"}],"explanation":["「~거든」·「~니까」는 까닭을 말할 때 써요.","「~하자」는 생각을 말할 때 써요.","인사말은 까닭이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#5','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 기르고 싶어 하는 것을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 기르고 싶어 하는 것을 알맞게 이어 보세요.","pairs":[{"l":"도윤","r":"물고기"},{"l":"하린","r":"강낭콩"},{"l":"지후","r":"달팽이"}],"mis":"K2-1-u6-X08","explanation":["도윤이는 물고기를 기르자고 했어요.","하린이는 강낭콩을 기르자고 했어요.","지후는 달팽이를 기르자고 했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 인물과 하고 싶은 놀이를 알맞게 이어 보세요.","pairs":[{"l":"서아","r":"피구"},{"l":"민호","r":"줄넘기"},{"l":"예린","r":"숨바꼭질"}],"explanation":["서아는 피구를 하자고 했어요.","민호는 줄넘기를 하자고 했어요.","예린이는 숨바꼭질을 하자고 했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#6','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 생각의 까닭이 드러난 말은 어느 것인가요?',ARRAY['K2-1-u6-X09']::text[],true,'{"seq":6,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 생각의 까닭이 드러난 말은 어느 것인가요?","options":[{"t":"「싹이 트고 자라는 모습을 날마다 볼 수 있거든.」","correct":true},{"t":"「강낭콩을 기르자.」","mis":"K2-1-u6-X09"},{"t":"「오늘 내 신발은 파란색이야.」","mis":"K2-1-u6-X09"}],"explanation":["「~볼 수 있거든」이 강낭콩을 기르자는 생각의 까닭이에요.","「기르자」는 생각이지 까닭이 아니에요.","신발 색깔은 까닭이 될 수 없어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대화를 읽고 답해 보세요. 생각의 까닭이 드러난 말은 어느 것인가요?","options":[{"t":"「우리 반 모두가 함께 뛸 수 있으니까.」","correct":true},{"t":"「피구를 하자.」","mis":"K2-1-u6-X09"},{"t":"「점심은 카레였어.」","mis":"K2-1-u6-X09"}],"explanation":["「~뛸 수 있으니까」가 피구를 하자는 생각의 까닭이에요.","「하자」는 생각이지 까닭이 아니에요.","점심 메뉴는 까닭이 될 수 없어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#7','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',2,'match','auto','대화를 읽고 인물과 그 생각의 까닭을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u6-C7","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각의 까닭을 알맞게 이어 보세요.","pairs":[{"l":"도윤","r":"돌보기 쉬워서"},{"l":"하린","r":"자라는 모습을 볼 수 있어서"},{"l":"지후","r":"귀엽고 만져 볼 수 있어서"}],"mis":"K2-1-u6-X08","explanation":["도윤이는 돌보기 쉽다고 했어요.","하린이는 자라는 모습을 볼 수 있다고 했어요.","지후는 귀엽고 만져 볼 수 있다고 했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대화를 읽고 인물과 그 생각의 까닭을 알맞게 이어 보세요.","pairs":[{"l":"서아","r":"모두가 함께 뛸 수 있어서"},{"l":"민호","r":"실력을 키울 수 있어서"},{"l":"예린","r":"규칙이 쉬워서"}],"explanation":["서아는 모두가 함께 뛸 수 있다고 했어요.","민호는 실력을 키울 수 있다고 했어요.","예린이는 규칙이 쉽다고 했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#8','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C6',2,'sa','auto','대화를 읽고 답해 보세요. 지후가 기르자고 한 것은 무엇인가요? 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u6-C6","difficulty":2,"kind":"sa","stem":"대화를 읽고 답해 보세요. 지후가 기르자고 한 것은 무엇인가요? 세 글자로 써 보세요.","answer":["달팽이"],"explanation":["지후는 「달팽이를 기르자.」라고 했어요.","지후의 생각은 달팽이를 기르자는 것이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 지호가 가고 싶어 한 곳은 어디인가요? 세 글자로 써 보세요.","answer":["과학관"],"explanation":["지호는 과학관에 가고 싶다고 했어요.","실험을 해 볼 수 있다는 까닭을 들었어요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#9','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 소율이가 동물원에 가고 싶은 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],true,'{"seq":9,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 소율이가 동물원에 가고 싶은 까닭은 무엇인가요?","options":[{"t":"책에서만 본 동물을 직접 볼 수 있어서","correct":true},{"t":"모래 놀이를 할 수 있어서","mis":"K2-1-u6-X08"},{"t":"실험을 해 볼 수 있어서","mis":"K2-1-u6-X08"}],"explanation":["소율이는 책에서만 본 동물을 직접 보고 싶다고 했어요.","모래 놀이는 하늘이가 말한 까닭이에요.","실험은 지호가 말한 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 하늘이가 바닷가에 가고 싶은 까닭은 무엇인가요?","options":[{"t":"모래 놀이도 하고 조개도 주울 수 있어서","correct":true},{"t":"동물을 직접 볼 수 있어서","mis":"K2-1-u6-X08"},{"t":"여러 가지 실험을 할 수 있어서","mis":"K2-1-u6-X08"}],"explanation":["하늘이는 모래 놀이와 조개 줍기를 까닭으로 들었어요.","동물은 소율이가 말한 까닭이에요.","실험은 지호가 말한 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#10','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「지후는 돌보기 쉬워서 달팽이를 기르자고 했어.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"채원 — 「하린이는 자라는 모습을 보려고 강낭콩을 기르자고 했어.」","mis":"K2-1-u6-X16"},{"t":"건우 — 「도윤이는 돌보기 쉬워서 물고기를 기르자고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「돌보기 쉬워서」는 도윤이가 말한 까닭이에요.","지후는 달팽이가 귀엽고 만져 볼 수 있다고 했어요.","채원이와 건우는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수빈 — 「서아는 규칙이 쉬워서 피구를 하자고 했어.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"시우 — 「민호는 실력을 키우려고 줄넘기를 하자고 했어.」","mis":"K2-1-u6-X16"},{"t":"다은 — 「예린이는 규칙이 쉬워서 숨바꼭질을 하자고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「규칙이 쉬워서」는 예린이가 말한 까닭이에요.","서아는 모두가 함께 뛸 수 있다고 했어요.","시우와 다은이는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#1','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 까닭이 드러나지 않은 말은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":1,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 까닭이 드러나지 않은 말은 어느 것인가요?","options":[{"t":"「과학관에 가고 싶어.」","correct":true},{"t":"「여러 가지 실험을 해 볼 수 있어서.」","mis":"K2-1-u6-X16"},{"t":"「모래 놀이도 하고 조개도 주울 수 있어서.」","mis":"K2-1-u6-X16"}],"explanation":["「과학관에 가고 싶어.」는 생각만 말했어요.","나머지 두 말은 생각의 까닭이에요.","물음의 「않은」에 동그라미를 쳐요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#2','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C6',2,'mc','auto','대화를 읽고 답해 보세요. 세 친구의 생각이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X07']::text[],false,'{"seq":2,"concept":"K2-1-u6-C6","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 세 친구의 생각이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"저마다 좋다고 여기는 점이 다르니까","correct":true},{"t":"셋 가운데 한 명만 맞으니까","mis":"K2-1-u6-X12"},{"t":"대화를 듣지 않았으니까","mis":"K2-1-u6-X07"}],"explanation":["사람마다 좋다고 여기는 점이 달라 생각이 달라요.","생각이 다르다고 한 명만 맞는 것은 아니에요.","세 친구는 대화를 나누며 생각을 말했어요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#3','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',3,'error','auto','까닭을 찾았어요. 까닭이 아닌 것을 까닭이라고 한 친구는 누구인가요?',ARRAY['K2-1-u6-X09','K2-1-u6-X16']::text[],false,'{"seq":3,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"까닭을 찾았어요. 까닭이 아닌 것을 까닭이라고 한 친구는 누구인가요?","options":[{"t":"도담 — 「서아가 피구를 하자고 한 까닭은 서아가 키가 커서야.」","correct":true,"mis_target":"K2-1-u6-X09"},{"t":"지안 — 「모두가 함께 뛸 수 있어서야.」","mis":"K2-1-u6-X16"},{"t":"하준 — 「서아는 우리 반 모두가 뛰는 게 좋다고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「키가 커서」는 대화에 없고 까닭도 아니에요.","서아는 모두가 함께 뛸 수 있다고 했어요.","지안이와 하준이는 바르게 찾았어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#4','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',3,'ox','auto','대화를 읽고 답해 보세요. 「달팽이를 기르자.」는 지후가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":4,"concept":"K2-1-u6-C7","difficulty":3,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「달팽이를 기르자.」는 지후가 말한 까닭이에요.","answer":"X","reason_options":[{"t":"「달팽이를 기르자.」는 생각이고, 까닭은 「귀엽고 만져 볼 수 있다」니까","correct":true},{"t":"「~하자」로 끝나는 말은 모두 까닭이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["「~하자」는 무엇을 하자는 생각이에요.","까닭은 「귀엽고 만져 볼 수 있거든」이에요.","생각과 까닭을 가려요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#5','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',3,'mc','auto','「나는 우산을 챙겨야 한다고 생각해. 왜냐하면 ( ).」 빈칸에 들어갈 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":5,"concept":"K2-1-u6-C7","difficulty":3,"kind":"mc","stem":"「나는 우산을 챙겨야 한다고 생각해. 왜냐하면 ( ).」 빈칸에 들어갈 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"오후에 비가 온다고 했거든","correct":true},{"t":"내 우산은 노란색이거든","mis":"K2-1-u6-X09"},{"t":"우산을 챙겨야 하거든","mis":"K2-1-u6-X09"}],"explanation":["비가 온다는 것이 우산을 챙길 까닭이에요.","우산 색깔은 까닭이 되지 않아요.","생각을 그대로 되풀이하는 것은 까닭이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#6','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C6',3,'mc','auto','「채원: 나는 급식에 나물이 자주 나왔으면 좋겠어. 몸에 좋으니까.」 채원이의 생각은 무엇인가요?',ARRAY['K2-1-u6-X09','K2-1-u6-X07']::text[],false,'{"seq":6,"concept":"K2-1-u6-C6","difficulty":3,"kind":"mc","stem":"「채원: 나는 급식에 나물이 자주 나왔으면 좋겠어. 몸에 좋으니까.」 채원이의 생각은 무엇인가요?","options":[{"t":"급식에 나물이 자주 나오면 좋겠다","correct":true},{"t":"나물은 몸에 좋다","mis":"K2-1-u6-X09"},{"t":"급식이 맛이 없다","mis":"K2-1-u6-X07"}],"explanation":["채원이의 생각은 나물이 자주 나오면 좋겠다는 거예요.","「몸에 좋으니까」는 그 생각의 까닭이에요.","맛이 없다는 말은 하지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#7','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',3,'mc','auto','대화를 읽고 답해 보세요. 교실에서 기르기에 가장 쉽다는 까닭을 든 친구는 누구인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":7,"concept":"K2-1-u6-C7","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 교실에서 기르기에 가장 쉽다는 까닭을 든 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"하린","mis":"K2-1-u6-X08"},{"t":"지후","mis":"K2-1-u6-X08"}],"explanation":["도윤이는 먹이만 주면 되어 돌보기 쉽다고 했어요.","하린이는 자라는 모습을 까닭으로 들었어요.","지후는 귀엽고 만질 수 있다는 까닭을 들었어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#8','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',4,'mc','auto','대화를 읽고 답해 보세요. 비가 오는 날 교실 안에서 놀아야 한다면, 세 친구의 까닭 가운데 그대로 쓸 수 있는 놀이는 어느 것인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X09']::text[],false,'{"seq":8,"concept":"K2-1-u6-C7","difficulty":4,"kind":"mc","stem":"대화를 읽고 답해 보세요. 비가 오는 날 교실 안에서 놀아야 한다면, 세 친구의 까닭 가운데 그대로 쓸 수 있는 놀이는 어느 것인가요?","options":[{"t":"숨바꼭질 — 규칙이 쉬워 누구나 할 수 있으니까","correct":true},{"t":"피구 — 모두가 함께 뛸 수 있으니까","mis":"K2-1-u6-X07"},{"t":"줄넘기 — 날마다 해야 하니까","mis":"K2-1-u6-X09"}],"explanation":["교실에서는 뛰거나 줄을 돌리기 어려워요.","숨바꼭질은 규칙이 쉬워 교실에서도 할 수 있어요.","「날마다 해야 하니까」는 대화에 없는 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#9','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',4,'essay','teacher','대화를 읽고 답해 보세요. 세 친구의 생각과 까닭을 「누가 — 생각 — 까닭」 차례로 정리해 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C7","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 세 친구의 생각과 까닭을 「누가 — 생각 — 까닭」 차례로 정리해 써 보세요.","answer_guide":{"answer":"예: 소율 — 동물원에 가고 싶다 — 책에서만 본 동물을 직접 볼 수 있어서. 지호 — 과학관에 가고 싶다 — 여러 가지 실험을 해 볼 수 있어서. 하늘 — 바닷가에 가고 싶다 — 모래 놀이와 조개 줍기를 할 수 있어서.","scoring_points":["세 인물을 모두 썼는가","인물마다 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가"]},"explanation":["세 인물.","인물마다 생각.","짝이 되는 까닭."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#10','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C6',4,'essay','teacher','가족이나 친구가 무언가를 하자고 말한 일을 떠올려, 그 사람의 생각과 까닭을 찾아 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"가족이나 친구가 무언가를 하자고 말한 일을 떠올려, 그 사람의 생각과 까닭을 찾아 써 보세요.","answer_guide":{"answer":"예: 엄마는 주말에 공원에 가자고 하셨어요(생각). 왜냐하면 날씨가 좋아서 산책하기 좋기 때문이에요(까닭).","scoring_points":["누구의 말인지 썼는가","그 사람의 생각을 찾아 썼는가","생각과 짝이 되는 까닭을 썼는가"]},"explanation":["누구의 말.","생각.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#1','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C7',1,'mc','auto','글을 읽고 답해 보세요. 개구리가 반장이 되겠다고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X07']::text[],true,'{"seq":1,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 개구리가 반장이 되겠다고 한 까닭은 무엇인가요?","options":[{"t":"목소리가 커서 알릴 일을 잘 전할 수 있어서","correct":true},{"t":"차분해서 꼼꼼하게 살필 수 있어서","mis":"K2-1-u6-X08"},{"t":"연못에서 가장 오래 살아서","mis":"K2-1-u6-X07"}],"explanation":["개구리는 목소리가 크다는 까닭을 들었어요.","차분하다는 것은 거북이 든 까닭이에요.","오래 살았다는 말은 글에 없어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 오리가 반장이 되겠다고 한 까닭은 무엇인가요?","options":[{"t":"헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어서","correct":true},{"t":"목소리가 커서","mis":"K2-1-u6-X08"},{"t":"깃털 색이 예뻐서","mis":"K2-1-u6-X07"}],"explanation":["오리는 헤엄치고 날 수 있다는 까닭을 들었어요.","목소리가 크다는 것은 개구리가 든 까닭이에요.","깃털 색은 글에 없어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#2','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11']::text[],true,'{"seq":2,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각과 그렇게 생각한 까닭","correct":true},{"t":"큰 소리로 우기기","mis":"K2-1-u6-X11"},{"t":"친구 말 무시하기","mis":"K2-1-u6-X11"}],"explanation":["내 생각과 까닭을 함께 말해야 잘 전해져요.","우기면 친구가 듣기 싫어해요.","친구 말을 무시하면 서로 생각을 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"예의 바른 말","correct":true},{"t":"친구 말 끊기","mis":"K2-1-u6-X11"},{"t":"화난 목소리","mis":"K2-1-u6-X11"}],"explanation":["예의 바르게 말하면 친구도 잘 들어 줘요.","친구 말을 끊으면 예의에 어긋나요.","화난 목소리로 말하면 생각이 잘 전해지지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#3','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',1,'ox','auto','내 생각을 말할 때는 「나는 ~라고 생각해. 왜냐하면 ~거든.」처럼 말하면 좋아요.',ARRAY['K2-1-u6-X10']::text[],true,'{"seq":3,"concept":"K2-1-u6-C8","difficulty":1,"kind":"ox","stem":"내 생각을 말할 때는 「나는 ~라고 생각해. 왜냐하면 ~거든.」처럼 말하면 좋아요.","answer":"O","reason_options":[{"t":"생각과 까닭이 함께 또렷하게 드러나니까","correct":true},{"t":"까닭은 마지막까지 숨겨야 하니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["이렇게 말하면 생각과 까닭이 함께 드러나요.","듣는 사람이 내 생각을 잘 이해해요.","생각 뒤에 까닭을 붙여요."],"variant_rule":{"alt":[{"stem":"친구의 생각이 나와 다르면 친구의 생각은 틀린 거예요.","answer":"X","reason_options":[{"t":"사람마다 좋다고 여기는 점이 달라 생각이 다를 수 있으니까","correct":true},{"t":"나와 같은 생각만 맞는 생각이니까","mis":"K2-1-u6-X12"}],"explanation":["생각은 사람마다 다를 수 있어요.","다르다고 틀린 것은 아니에요.","친구의 까닭을 들어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#4','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C6',1,'mc','auto','글을 읽고 답해 보세요. 반장이 되겠다고 말한 동물이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],true,'{"seq":4,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 반장이 되겠다고 말한 동물이 아닌 것은 어느 것인가요?","options":[{"t":"다람쥐","correct":true},{"t":"거북","mis":"K2-1-u6-X16"},{"t":"개구리","mis":"K2-1-u6-X16"}],"explanation":["글에는 개구리·거북·오리가 나와요.","다람쥐는 글에 나오지 않아요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 반장을 뽑으려는 곳은 어디인가요?","options":[{"t":"연못","correct":true},{"t":"숲속","mis":"K2-1-u6-X07"},{"t":"바닷가","mis":"K2-1-u6-X07"}],"explanation":["연못 동물들이 반장을 뽑기로 했어요.","숲속이나 바닷가는 글에 나오지 않아요.","글의 첫 문장을 살펴봐요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#5','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C7',2,'match','auto','글을 읽고 동물과 반장이 되려는 까닭을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C7","difficulty":2,"kind":"match","stem":"글을 읽고 동물과 반장이 되려는 까닭을 알맞게 이어 보세요.","pairs":[{"l":"개구리","r":"목소리가 커서"},{"l":"거북","r":"차분하고 꼼꼼해서"},{"l":"오리","r":"헤엄치고 날 수 있어서"}],"mis":"K2-1-u6-X08","explanation":["개구리는 목소리가 크다고 했어요.","거북은 차분하고 꼼꼼하다고 했어요.","오리는 헤엄치고 날 수 있다고 했어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"생각을 말하는 표현과 그 쓰임을 알맞게 이어 보세요.","pairs":[{"l":"나는 ~라고 생각해","r":"내 생각 말하기"},{"l":"왜냐하면 ~거든","r":"까닭 말하기"},{"l":"너는 어떻게 생각해?","r":"친구 생각 묻기"}],"explanation":["「나는 ~라고 생각해」로 내 생각을 말해요.","「왜냐하면 ~거든」으로 까닭을 말해요.","「너는 어떻게 생각해?」로 친구의 생각을 물어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#6','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',2,'mc','auto','글을 읽고 답해 보세요. 내 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],true,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 내 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 거북이 반장이 되면 좋겠어. 왜냐하면 꼼꼼하게 살펴서 실수가 적을 것 같거든.」","correct":true},{"t":"「나는 거북이 좋아. 그냥.」","mis":"K2-1-u6-X10"},{"t":"「거북이 무조건 반장이야. 다른 말 하지 마!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 예의 바르게 말했어요.","「그냥」은 까닭이 드러나지 않아요.","「다른 말 하지 마!」는 우기는 말이에요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 내 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 개구리가 반장이 되면 좋겠어. 왜냐하면 알릴 일을 모두에게 잘 들리게 전할 수 있거든.」","correct":true},{"t":"「개구리! 개구리! 개구리가 최고야!」","mis":"K2-1-u6-X11"},{"t":"「나는 개구리가 좋아. 왜냐하면 오늘 비가 오거든.」","mis":"K2-1-u6-X09"}],"explanation":["생각과 그에 맞는 까닭을 예의 바르게 말했어요.","이름만 외치는 것은 우기는 말이에요.","비가 오는 것은 이 생각의 까닭이 되지 않아요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#7','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',2,'mc','auto','친구가 나와 다른 생각을 말할 때 알맞은 태도는 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X11']::text[],true,'{"seq":7,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"친구가 나와 다른 생각을 말할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"끝까지 듣고 「그렇게 생각한 까닭이 뭐야?」 하고 물어봐요","correct":true},{"t":"「그건 틀렸어!」 하고 말을 끊어요","mis":"K2-1-u6-X12"},{"t":"못 들은 척하고 내 말만 해요","mis":"K2-1-u6-X11"}],"explanation":["끝까지 듣고 까닭을 물으면 친구 생각을 이해할 수 있어요.","다르다고 틀린 것은 아니에요.","내 말만 하면 생각을 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"생각을 나누면 좋은 점은 무엇인가요?","options":[{"t":"서로 다른 생각을 이해하고 존중하게 돼요","correct":true},{"t":"내 생각만 맞다는 것을 알게 돼요","mis":"K2-1-u6-X12"},{"t":"말을 크게 하는 연습이 돼요","mis":"K2-1-u6-X11"}],"explanation":["생각을 나누면 서로를 더 잘 이해해요.","내 생각만 맞는 것은 아니에요.","크게 말하는 것이 목적이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#8','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',2,'blank','auto','「나는 학급 문고에 만화책을 더 두면 좋겠다고 생각해. (     ) 책을 싫어하는 친구도 즐겁게 읽을 수 있거든.」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u6-X10']::text[],true,'{"seq":8,"concept":"K2-1-u6-C8","difficulty":2,"kind":"blank","stem":"「나는 학급 문고에 만화책을 더 두면 좋겠다고 생각해. (     ) 책을 싫어하는 친구도 즐겁게 읽을 수 있거든.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그러니까 이제","mis":"K2-1-u6-X10"},{"t":"하지만","mis":"K2-1-u6-X10"}],"explanation":["까닭을 이끌 때는 「왜냐하면」을 써요.","「그러니까 이제」·「하지만」은 까닭을 이끄는 말이 아니에요.","생각 뒤에 까닭을 이어 말해요."],"variant_rule":{"alt":[{"stem":"「나는 쉬는 시간이 조금 더 길면 좋겠다고 생각해. (     ) 화장실도 다녀오고 다음 시간 준비도 할 수 있거든.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그래도","mis":"K2-1-u6-X10"},{"t":"그런데","mis":"K2-1-u6-X10"}],"explanation":["까닭을 이끌 때는 「왜냐하면」을 써요.","「그래도」·「그런데」는 까닭을 이끄는 말이 아니에요.","생각 뒤에 까닭을 이어 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#9','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',2,'mc','auto','내 생각을 표현하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],true,'{"seq":9,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"내 생각을 표현하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인물의 생각과 까닭 알기 → 내 생각 정하기 → 까닭과 함께 말하기","correct":true},{"t":"까닭 없이 말하기 → 끝내기","mis":"K2-1-u6-X10"},{"t":"친구 생각 무시하기 → 내 생각 우기기","mis":"K2-1-u6-X11"}],"explanation":["먼저 인물의 생각을 알고, 내 생각을 정하고, 까닭과 함께 말해요.","까닭 없이 말하면 생각이 잘 전해지지 않아요.","우기거나 무시하면 생각을 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"생각을 글과 그림으로 나타낼 때 함께 쓰면 좋은 것은 어느 것인가요?","options":[{"t":"그렇게 생각한 까닭","correct":true},{"t":"친구의 비밀","mis":"K2-1-u6-X13"},{"t":"그림의 크기 숫자","mis":"K2-1-u6-X03"}],"explanation":["그림과 함께 까닭을 쓰면 생각이 잘 전해져요.","친구의 비밀은 쓰면 안 돼요.","그림 크기는 생각과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#10','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',3,'error','auto','반장 뽑기에 대해 생각을 말했어요. 예의 바르지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X11','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"반장 뽑기에 대해 생각을 말했어요. 예의 바르지 않게 말한 친구는 누구인가요?","options":[{"t":"건우 — 「오리 말고 딴 거 고른 애들은 다 바보야.」","correct":true,"mis_target":"K2-1-u6-X11"},{"t":"수빈 — 「나는 오리가 좋다고 생각해. 연못을 두루 살필 수 있거든.」","mis":"K2-1-u6-X16"},{"t":"윤호 — 「나는 거북이 좋아. 꼼꼼하니까. 너는 어떻게 생각해?」","mis":"K2-1-u6-X16"}],"explanation":["친구를 바보라고 하는 것은 예의 바르지 않아요.","생각이 달라도 친구를 존중해요.","수빈이와 윤호는 까닭을 들어 예의 바르게 말했어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 반장 뽑기에 대해 생각을 말했어요. 예의 바르지 않게 말한 친구는 누구인가요?","options":[{"t":"채원 — 「개구리는 시끄럽기만 해. 너희 생각은 다 틀렸어!」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"지호 — 「나는 개구리가 좋다고 생각해. 알릴 일을 잘 전하거든.」","mis":"K2-1-u6-X16"},{"t":"하윤 — 「나는 오리가 좋아. 그런데 거북의 까닭도 일리가 있어.」","mis":"K2-1-u6-X16"}],"explanation":["친구들의 생각이 다 틀렸다는 말은 다른 생각을 존중하지 않아요.","생각이 달라도 까닭을 들어 봐요.","지호와 하윤이는 예의 바르게 말했어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#1','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',2,'mc','auto','글을 읽고 답해 보세요. 「나는 오리가 반장이 되면 좋겠어.」 다음에 이어 말할 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X09','K2-1-u6-X08']::text[],false,'{"seq":1,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「나는 오리가 반장이 되면 좋겠어.」 다음에 이어 말할 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「연못 구석구석을 둘러보며 친구들을 살필 수 있거든.」","correct":true},{"t":"「오리는 꽥꽥 울거든.」","mis":"K2-1-u6-X09"},{"t":"「개구리 목소리가 크거든.」","mis":"K2-1-u6-X08"}],"explanation":["오리가 반장이면 좋은 점을 까닭으로 들었어요.","꽥꽥 우는 것은 반장이 되면 좋은 까닭이 아니에요.","목소리는 개구리에 대한 까닭이에요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#2','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',2,'mc','auto','친구가 「나는 거북이 좋다고 생각해.」라고만 말했어요. 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X11']::text[],false,'{"seq":2,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"친구가 「나는 거북이 좋다고 생각해.」라고만 말했어요. 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「왜 그렇게 생각했는지 까닭도 말해 줄래?」","correct":true},{"t":"「그건 틀렸어.」","mis":"K2-1-u6-X12"},{"t":"「됐어, 내 말이나 들어.」","mis":"K2-1-u6-X11"}],"explanation":["까닭을 물으면 친구의 생각을 더 잘 알 수 있어요.","다른 생각을 틀렸다고 하면 안 돼요.","친구 말을 무시하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#3','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'error','auto','「교실 생물로 무엇을 기를까?」에 대해 생각을 말했어요. 까닭이 생각과 어울리지 않는 친구는 누구인가요?',ARRAY['K2-1-u6-X09','K2-1-u6-X16']::text[],false,'{"seq":3,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「교실 생물로 무엇을 기를까?」에 대해 생각을 말했어요. 까닭이 생각과 어울리지 않는 친구는 누구인가요?","options":[{"t":"태민 — 「나는 물고기를 기르면 좋겠어. 왜냐하면 나는 물고기 그림을 그렸거든.」","correct":true,"mis_target":"K2-1-u6-X09"},{"t":"아린 — 「나는 강낭콩이 좋아. 날마다 키를 재어 볼 수 있거든.」","mis":"K2-1-u6-X16"},{"t":"서윤 — 「나는 달팽이가 좋아. 조용해서 공부에 방해가 안 되거든.」","mis":"K2-1-u6-X16"}],"explanation":["물고기 그림을 그린 것은 물고기를 기를 까닭이 되지 않아요.","까닭은 생각을 뒷받침하는 좋은 점이어야 해요.","아린이와 서윤이는 어울리는 까닭을 들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#4','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'ox','auto','친구와 생각이 다를 때에는 내 생각이 맞다고 끝까지 큰 소리로 말해야 해요.',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":4,"concept":"K2-1-u6-C8","difficulty":3,"kind":"ox","stem":"친구와 생각이 다를 때에는 내 생각이 맞다고 끝까지 큰 소리로 말해야 해요.","answer":"X","reason_options":[{"t":"까닭을 들어 차분히 말하고 친구의 생각도 들어야 하니까","correct":true},{"t":"큰 소리로 말하는 사람의 생각이 맞으니까","mis":"K2-1-u6-X11"}],"mis":"K2-1-u6-X11","explanation":["큰 소리로 우기면 생각이 잘 전해지지 않아요.","까닭을 들어 차분히 말해요.","친구의 생각도 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#5','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'mc','auto','글을 읽고 답해 보세요. 세 동물의 까닭을 모두 들은 뒤 내 생각을 정하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X09']::text[],false,'{"seq":5,"concept":"K2-1-u6-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 세 동물의 까닭을 모두 들은 뒤 내 생각을 정하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"반장에게 가장 필요한 일이 무엇인지 생각하고, 그 일을 잘할 동물을 고른다","correct":true},{"t":"가장 먼저 말한 동물을 고른다","mis":"K2-1-u6-X10"},{"t":"내가 키우고 싶은 동물을 고른다","mis":"K2-1-u6-X09"}],"explanation":["반장이 할 일을 생각하면 까닭을 견주어 고를 수 있어요.","먼저 말했다고 좋은 반장은 아니에요.","키우고 싶은 것은 반장을 고르는 까닭이 아니에요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#6','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'mc','auto','친구의 생각에 찬성하지 않을 때 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X11']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":3,"kind":"mc","stem":"친구의 생각에 찬성하지 않을 때 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「네 생각도 좋아. 그런데 나는 조금 다르게 생각해. 왜냐하면 ~」","correct":true},{"t":"「그런 생각을 하다니 이상해.」","mis":"K2-1-u6-X12"},{"t":"「말도 안 돼. 내 말이 맞아.」","mis":"K2-1-u6-X11"}],"explanation":["친구 생각을 인정하고 내 생각과 까닭을 말했어요.","「이상해」는 친구 생각을 무시하는 말이에요.","「말도 안 돼」는 우기는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#7','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'mc','auto','「우리 반 이름을 무엇으로 할까?」에 대한 생각을 가장 잘 표현한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":7,"concept":"K2-1-u6-C8","difficulty":3,"kind":"mc","stem":"「우리 반 이름을 무엇으로 할까?」에 대한 생각을 가장 잘 표현한 것은 어느 것인가요?","options":[{"t":"「나는 「햇살반」이 좋다고 생각해. 왜냐하면 우리 반이 늘 밝고 따뜻했으면 좋겠거든.」","correct":true},{"t":"「햇살반. 끝.」","mis":"K2-1-u6-X10"},{"t":"「햇살반 안 하면 나 안 놀 거야.」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","「끝.」은 까닭이 없어요.","안 놀겠다는 말은 우기는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#8','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',4,'mc','auto','글을 읽고 답해 보세요. 「거북은 느려서 반장이 될 수 없어.」라는 친구의 말에 예의 바르게 다른 생각을 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X07']::text[],false,'{"seq":8,"concept":"K2-1-u6-C8","difficulty":4,"kind":"mc","stem":"글을 읽고 답해 보세요. 「거북은 느려서 반장이 될 수 없어.」라는 친구의 말에 예의 바르게 다른 생각을 말한 것은 어느 것인가요?","options":[{"t":"「느린 건 맞아. 하지만 차분해서 꼼꼼하게 살피는 것도 반장에게 필요하다고 생각해.」","correct":true},{"t":"「너는 거북을 싫어하는구나. 나쁘다.」","mis":"K2-1-u6-X12"},{"t":"「거북은 빠르거든!」","mis":"K2-1-u6-X07"}],"explanation":["친구 말을 인정하면서 까닭을 들어 내 생각을 말했어요.","친구를 나쁘다고 하면 안 돼요.","거북이 빠르다는 것은 글과 달라요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#9','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',4,'essay','teacher','글을 읽고 답해 보세요. 연못 반장으로 누가 되면 좋을지 내 생각을 정하고, 그렇게 생각한 까닭을 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 연못 반장으로 누가 되면 좋을지 내 생각을 정하고, 그렇게 생각한 까닭을 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 써 보세요.","answer_guide":{"answer":"예: 나는 오리가 반장이 되면 좋겠다고 생각해요. 왜냐하면 헤엄도 치고 날 수도 있어서 연못 구석구석의 친구들을 빠짐없이 살필 수 있기 때문이에요.","scoring_points":["누가 되면 좋을지 내 생각을 썼는가","글의 내용을 바탕으로 까닭을 썼는가","「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","글을 바탕으로 한 까닭.","알맞은 꼴."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#10','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',4,'essay','teacher','짝과 생각이 달랐던 일을 떠올려, 짝의 생각과 까닭, 내 생각과 까닭을 쓰고, 짝의 생각을 존중하는 말을 한 문장 덧붙여 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"짝과 생각이 달랐던 일을 떠올려, 짝의 생각과 까닭, 내 생각과 까닭을 쓰고, 짝의 생각을 존중하는 말을 한 문장 덧붙여 보세요.","answer_guide":{"answer":"예: 짝은 피구를 하자고 했어요. 모두 뛸 수 있어서래요. 나는 줄넘기가 좋다고 생각했어요. 실력을 키울 수 있어서요. 「네 말처럼 다 같이 뛰는 것도 정말 좋겠다.」","scoring_points":["짝의 생각과 까닭을 썼는가","내 생각과 까닭을 썼는가","짝의 생각을 존중하는 말을 썼는가"]},"explanation":["짝의 생각과 까닭.","내 생각과 까닭.","존중하는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#1','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',1,'mc','auto','책 소개 상자의 앞면에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],true,'{"seq":1,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자의 앞면에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"책 제목과 인상 깊은 장면","correct":true},{"t":"시험 점수","mis":"K2-1-u6-X13"},{"t":"내일 날씨","mis":"K2-1-u6-X13"}],"explanation":["앞면에는 한눈에 어떤 책인지 알 수 있게 제목과 장면을 담아요.","시험 점수는 책과 상관없어요.","날씨는 책 소개와 상관없어요."],"variant_rule":{"alt":[{"stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"기억에 남는 문장","correct":true},{"t":"우리 집 전화번호","mis":"K2-1-u6-X13"},{"t":"게임 비밀번호","mis":"K2-1-u6-X13"}],"explanation":["책에서 기억에 남는 문장은 책을 소개하는 데 좋아요.","전화번호는 책과 상관없고 남에게 알리면 안 돼요.","비밀번호도 책과 상관없고 알리면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#2','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',1,'mc','auto','상자를 읽고 답해 보세요. 수빈이가 소개한 책의 제목은 무엇인가요?',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":2,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이가 소개한 책의 제목은 무엇인가요?","options":[{"t":"달팽이 우체부","correct":true},{"t":"비 오는 날","mis":"K2-1-u6-X07"},{"t":"숲속 편지","mis":"K2-1-u6-X07"}],"explanation":["앞면에 「제목: 달팽이 우체부」라고 썼어요.","「비 오는 날」은 그림의 내용이에요.","「숲속 편지」라는 제목은 상자에 없어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"},"variant_rule":{"alt":[{"stem":"상자를 읽고 답해 보세요. 수빈이가 기억에 남는 문장을 쓴 곳은 어디인가요?","options":[{"t":"왼쪽 면","correct":true},{"t":"앞면","mis":"K2-1-u6-X14"},{"t":"오른쪽 면","mis":"K2-1-u6-X14"}],"explanation":["왼쪽 면에 기억에 남는 문장을 썼어요.","앞면에는 제목과 그림을 담았어요.","오른쪽 면에는 생각을 썼어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#3','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',1,'ox','auto','같은 책을 읽어도 친구마다 생각이나 느낌이 다를 수 있어요.',ARRAY['K2-1-u6-X12']::text[],true,'{"seq":3,"concept":"K2-1-u6-C9","difficulty":1,"kind":"ox","stem":"같은 책을 읽어도 친구마다 생각이나 느낌이 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 인상 깊은 부분과 느낌이 다르니까","correct":true},{"t":"같은 책을 읽으면 모두 같은 생각을 해야 하니까","mis":"K2-1-u6-X12"}],"mis":"K2-1-u6-X12","explanation":["같은 책도 사람마다 다르게 느낄 수 있어요.","친구의 소개를 들으면 새로운 생각을 알게 돼요.","다른 생각도 존중해요."],"variant_rule":{"alt":[{"stem":"책 소개 상자에는 책의 줄거리만 쓰고 내 생각이나 느낌은 쓰지 않아요.","answer":"X","reason_options":[{"t":"읽고 든 생각이나 느낌도 함께 담아야 하니까","correct":true},{"t":"책 소개에는 내 생각이 필요 없으니까","mis":"K2-1-u6-X14"}],"explanation":["책 소개 상자의 한 면에는 생각이나 느낌을 써요.","내 생각을 담으면 친구가 책에 더 관심을 가져요.","줄거리와 생각을 함께 담아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#4','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',1,'mc','auto','책 소개 상자를 만든 뒤에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X14']::text[],true,'{"seq":4,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자를 만든 뒤에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"친구들에게 발표하고 교실에 전시해요","correct":true},{"t":"아무에게도 보여 주지 않아요","mis":"K2-1-u6-X14"},{"t":"상자를 바로 버려요","mis":"K2-1-u6-X14"}],"explanation":["완성한 상자를 발표하고 전시하면 서로의 책을 알 수 있어요.","혼자만 가지고 있으면 소개가 되지 않아요.","버리면 친구들이 볼 수 없어요."],"variant_rule":{"alt":[{"stem":"친구의 책 소개를 들을 때 알맞은 태도는 어느 것인가요?","options":[{"t":"끝까지 귀 기울여 듣고 궁금한 것을 물어봐요","correct":true},{"t":"다른 친구와 떠들어요","mis":"K2-1-u6-X11"},{"t":"「그 책 재미없어.」라고 끊어요","mis":"K2-1-u6-X12"}],"explanation":["끝까지 들으면 친구의 생각을 알 수 있어요.","떠들면 친구의 소개를 듣지 못해요.","친구의 생각을 무시하는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#5','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'match','auto','책 소개 상자의 면과 담을 내용을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C9","difficulty":2,"kind":"match","stem":"책 소개 상자의 면과 담을 내용을 알맞게 이어 보세요.","pairs":[{"l":"앞면","r":"제목과 인상 깊은 장면"},{"l":"왼쪽 면","r":"기억에 남는 문장"},{"l":"오른쪽 면","r":"생각이나 느낌"}],"mis":"K2-1-u6-X14","explanation":["앞면에는 제목과 장면을 담아요.","왼쪽 면에는 기억에 남는 문장을 써요.","오른쪽 면에는 생각이나 느낌을 써요."],"variant_rule":{"alt":[{"stem":"책 소개에 담을 내용과 그 까닭을 알맞게 이어 보세요.","pairs":[{"l":"제목","r":"어떤 책인지 알려 주려고"},{"l":"기억에 남는 문장","r":"책의 말맛을 느끼게 하려고"},{"l":"생각이나 느낌","r":"내가 왜 좋았는지 전하려고"}],"explanation":["제목은 어떤 책인지 알려 줘요.","기억에 남는 문장은 책의 말맛을 느끼게 해요.","생각이나 느낌은 왜 좋았는지 전해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#6','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'mc','auto','상자를 읽고 답해 보세요. 수빈이가 이 책을 읽고 든 생각은 무엇인가요?',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":6,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이가 이 책을 읽고 든 생각은 무엇인가요?","options":[{"t":"느려도 끝까지 해내는 달팽이가 멋지다","correct":true},{"t":"달팽이는 너무 느려서 답답하다","mis":"K2-1-u6-X07"},{"t":"편지는 빨리 보내야 한다","mis":"K2-1-u6-X07"}],"explanation":["오른쪽 면에 달팽이가 멋지다는 생각을 썼어요.","답답하다는 말은 상자에 없어요.","빨리 보내야 한다는 말도 상자에 없어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"},"variant_rule":{"alt":[{"stem":"상자를 읽고 답해 보세요. 수빈이가 달팽이를 멋지다고 생각한 까닭은 무엇인가요?","options":[{"t":"비가 와도 포기하지 않았기 때문에","correct":true},{"t":"달팽이 껍데기가 예뻐서","mis":"K2-1-u6-X09"},{"t":"편지를 쓸 줄 알아서","mis":"K2-1-u6-X09"}],"explanation":["「포기하지 않았기 때문」이 까닭이에요.","껍데기가 예쁘다는 말은 상자에 없어요.","편지를 쓴다는 것은 까닭으로 들지 않았어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#7','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'mc','auto','책 소개 상자에 담기에 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],true,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"책 소개 상자에 담기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 집 주소","correct":true},{"t":"인상 깊은 장면 그림","mis":"K2-1-u6-X16"},{"t":"책을 읽고 든 느낌","mis":"K2-1-u6-X16"}],"explanation":["친구의 집 주소는 책과 상관없고 알리면 안 돼요.","장면 그림과 느낌은 책 소개에 알맞아요.","물음의 「않은」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책 소개 상자에 담기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"받아쓰기 점수","correct":true},{"t":"책의 제목","mis":"K2-1-u6-X16"},{"t":"기억에 남는 문장","mis":"K2-1-u6-X16"}],"explanation":["받아쓰기 점수는 책과 상관없어요.","제목과 기억에 남는 문장은 책 소개에 알맞아요.","물음의 「않은」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#8','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'sa','auto','책을 소개하는 말이에요. 「제가 소개할 책은 「달팽이 우체부」이고, 달팽이가 포기하지 않는 점이 (     ).」 빈칸에 어울리는 말을 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u6-C9","difficulty":2,"kind":"sa","stem":"책을 소개하는 말이에요. 「제가 소개할 책은 「달팽이 우체부」이고, 달팽이가 포기하지 않는 점이 (     ).」 빈칸에 어울리는 말을 써 보세요.","answer":["좋았어요","좋았습니다","멋졌어요","인상 깊었어요","감동적이었어요","좋았다","멋졌다"],"explanation":["책의 좋은 점을 소개할 때 「좋았어요」처럼 말해요.","「멋졌어요」·「인상 깊었어요」도 좋아요.","책의 어떤 점이 좋았는지 함께 말해요."],"variant_rule":{"alt":[{"stem":"책을 소개하는 말이에요. 「이 책에서 가장 기억에 남는 (     )은 「늦어도 괜찮아.」예요.」 빈칸에 알맞은 낱말을 두 글자로 써 보세요.","answer":["문장"],"explanation":["「늦어도 괜찮아.」는 책 속의 문장이에요.","기억에 남는 문장을 소개하면 책의 말맛이 전해져요.","책 소개 상자의 한 면에 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#9','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'mc','auto','책을 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X14','K2-1-u6-X11']::text[],true,'{"seq":9,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"책을 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「제가 소개할 책은 「달팽이 우체부」예요. 끝까지 해내는 달팽이가 멋져서 꼭 읽어 보면 좋겠어요.」","correct":true},{"t":"「책이 있어요. 끝.」","mis":"K2-1-u6-X14"},{"t":"「이 책 안 읽으면 바보야.」","mis":"K2-1-u6-X11"}],"explanation":["제목과 좋았던 점, 권하는 말을 함께 말했어요.","「끝.」만으로는 어떤 책인지 알 수 없어요.","바보라는 말은 예의 바르지 않아요."],"variant_rule":{"alt":[{"stem":"책을 소개할 때 함께 말하면 좋은 것은 어느 것인가요?","options":[{"t":"그 책이 좋았던 까닭","correct":true},{"t":"책을 산 가게 이름","mis":"K2-1-u6-X13"},{"t":"책의 무게","mis":"K2-1-u6-X13"}],"explanation":["좋았던 까닭을 말하면 친구가 책에 관심을 가져요.","가게 이름은 책 소개와 상관없어요.","책의 무게도 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#10','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',3,'error','auto','책 소개 상자를 만들었어요. 알맞지 않게 만든 친구는 누구인가요?',ARRAY['K2-1-u6-X13','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C9","difficulty":3,"kind":"error","stem":"책 소개 상자를 만들었어요. 알맞지 않게 만든 친구는 누구인가요?","options":[{"t":"하준 — 「앞면에 제목 대신 내 비밀번호를 크게 썼어.」","correct":true,"mis_target":"K2-1-u6-X13"},{"t":"예린 — 「왼쪽 면에 기억에 남는 문장을 썼어.」","mis":"K2-1-u6-X16"},{"t":"소율 — 「오른쪽 면에 읽고 든 느낌을 썼어.」","mis":"K2-1-u6-X16"}],"explanation":["비밀번호는 책과 상관없고 남에게 알리면 안 돼요.","앞면에는 제목과 인상 깊은 장면을 담아요.","예린이와 소율이는 알맞게 만들었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책 소개 상자를 만들었어요. 알맞지 않게 만든 친구는 누구인가요?","options":[{"t":"지안 — 「세 면에 모두 줄거리만 썼어. 내 느낌은 안 썼어.」","correct":true,"mis_target":"K2-1-u6-X14"},{"t":"도윤 — 「앞면에 제목과 장면을 그렸어.」","mis":"K2-1-u6-X16"},{"t":"민지 — 「한 면에 「나는 이 책이 따뜻했다」라고 썼어.」","mis":"K2-1-u6-X16"}],"explanation":["줄거리만 쓰고 느낌을 빠뜨리면 내 생각이 전해지지 않아요.","한 면에는 생각이나 느낌을 써요.","도윤이와 민지는 알맞게 만들었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#1','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',2,'mc','auto','상자를 읽고 답해 보세요. 앞면 그림으로 「비 오는 날 달팽이가 편지를 들고 기어가는 그림」을 고른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":1,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"상자를 읽고 답해 보세요. 앞면 그림으로 「비 오는 날 달팽이가 편지를 들고 기어가는 그림」을 고른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"책의 인상 깊은 장면이라서","correct":true},{"t":"그리기 가장 쉬워서","mis":"K2-1-u6-X09"},{"t":"달팽이가 싫어서","mis":"K2-1-u6-X09"}],"explanation":["앞면에는 가장 인상 깊은 장면을 그려요.","그리기 쉬워서 고르는 것은 알맞은 까닭이 아니에요.","싫어서라는 말은 상자의 생각과 맞지 않아요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#2','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',2,'mc','auto','친구의 책 소개를 듣고 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X11']::text[],false,'{"seq":2,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"친구의 책 소개를 듣고 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「달팽이가 어떻게 끝까지 해냈는지 궁금해. 나도 읽어 볼래.」","correct":true},{"t":"「달팽이 이야기는 다 똑같아.」","mis":"K2-1-u6-X12"},{"t":"「내 책이 더 재미있어.」","mis":"K2-1-u6-X11"}],"explanation":["궁금한 점을 말하고 관심을 보였어요.","다 똑같다는 말은 친구 소개를 무시해요.","내 책 자랑만 하면 친구가 서운해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#3','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'error','auto','같은 책을 읽고 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":3,"concept":"K2-1-u6-C9","difficulty":3,"kind":"error","stem":"같은 책을 읽고 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"시우 — 「달팽이가 답답하다고? 네 생각은 틀렸어.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"하늘 — 「나는 달팽이가 멋졌어. 너는 답답했구나. 왜 그랬어?」","mis":"K2-1-u6-X16"},{"t":"로아 — 「나도 처음엔 답답했는데 끝에는 멋졌어.」","mis":"K2-1-u6-X16"}],"explanation":["같은 책도 생각이 다를 수 있어요.","다른 생각을 틀렸다고 하면 안 돼요.","하늘이와 로아는 생각을 존중하며 나눴어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#4','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'ox','auto','상자를 읽고 답해 보세요. 수빈이는 오른쪽 면에 생각과 함께 그렇게 생각한 까닭도 썼어요.',ARRAY['K2-1-u6-X14']::text[],false,'{"seq":4,"concept":"K2-1-u6-C9","difficulty":3,"kind":"ox","stem":"상자를 읽고 답해 보세요. 수빈이는 오른쪽 면에 생각과 함께 그렇게 생각한 까닭도 썼어요.","answer":"O","reason_options":[{"t":"「왜냐하면 비가 와도 포기하지 않았기 때문」이라고 썼으니까","correct":true},{"t":"오른쪽 면에는 제목만 썼으니까","mis":"K2-1-u6-X14"}],"mis":"K2-1-u6-X14","explanation":["오른쪽 면에 생각과 까닭을 함께 썼어요.","까닭을 쓰면 생각이 더 잘 전해져요.","제목은 앞면에 있어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#5','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'mc','auto','책 소개 상자의 왼쪽 면에 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」를 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X14']::text[],false,'{"seq":5,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"책 소개 상자의 왼쪽 면에 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」를 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"책의 주제가 잘 드러나 기억에 남는 문장이라서","correct":true},{"t":"가장 짧은 문장이라서","mis":"K2-1-u6-X14"},{"t":"책의 맨 처음 문장이라서","mis":"K2-1-u6-X14"}],"explanation":["이 문장은 달팽이의 마음이 잘 드러나 기억에 남아요.","짧다고 기억에 남는 문장은 아니에요.","맨 처음 문장이라고 고르는 것은 아니에요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#6','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'mc','auto','책 소개 상자의 뒷면을 더 채운다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":6,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"책 소개 상자의 뒷면을 더 채운다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이 책을 권하고 싶은 친구와 그 까닭","correct":true},{"t":"내가 좋아하는 게임 이름","mis":"K2-1-u6-X13"},{"t":"우리 집 강아지 사진","mis":"K2-1-u6-X13"}],"explanation":["책을 권하고 싶은 친구와 까닭은 책 소개에 어울려요.","게임 이름은 책과 상관없어요.","강아지 사진도 책 소개와 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#7','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'mc','auto','「같은 책 다른 생각」 시간에 알게 될 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X14']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"「같은 책 다른 생각」 시간에 알게 될 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 책도 친구마다 인상 깊은 부분이 다르다는 것","correct":true},{"t":"모두가 같은 장면을 좋아해야 한다는 것","mis":"K2-1-u6-X12"},{"t":"책은 혼자 읽고 말하지 않는다는 것","mis":"K2-1-u6-X14"}],"explanation":["같은 책을 읽어도 인상 깊은 부분이 다를 수 있어요.","모두 같아야 하는 것은 아니에요.","생각을 나누면 책 읽는 즐거움이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#8','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',4,'mc','auto','상자를 읽고 답해 보세요. 수빈이의 상자를 보고 친구에게 더 잘 소개하려면 무엇을 더하면 가장 좋을까요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":8,"concept":"K2-1-u6-C9","difficulty":4,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이의 상자를 보고 친구에게 더 잘 소개하려면 무엇을 더하면 가장 좋을까요?","options":[{"t":"이 책을 누구에게 권하고 싶은지와 그 까닭","correct":true},{"t":"수빈이의 받아쓰기 점수","mis":"K2-1-u6-X13"},{"t":"달팽이 우체부의 가격","mis":"K2-1-u6-X13"}],"explanation":["권하고 싶은 사람과 까닭을 더하면 소개가 풍성해져요.","받아쓰기 점수는 책과 상관없어요.","가격은 책의 내용을 알려 주지 않아요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#9','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',4,'essay','teacher','최근에 읽은 책 한 권으로 책 소개 상자를 만든다고 생각하고, 앞면·왼쪽 면·오른쪽 면에 담을 내용을 각각 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C9","difficulty":4,"kind":"essay","stem":"최근에 읽은 책 한 권으로 책 소개 상자를 만든다고 생각하고, 앞면·왼쪽 면·오른쪽 면에 담을 내용을 각각 써 보세요.","answer_guide":{"answer":"예: 앞면 — 제목 「심심한 고양이」, 고양이가 창밖을 보는 장면. 왼쪽 면 — 「심심할 땐 친구를 찾아가 봐.」 오른쪽 면 — 친구를 찾아 나서는 고양이가 용감하다고 생각해요. 왜냐하면 처음 가는 길이 무서웠을 텐데 끝까지 갔기 때문이에요.","scoring_points":["앞면에 제목과 인상 깊은 장면을 썼는가","왼쪽 면에 기억에 남는 문장을 썼는가","오른쪽 면에 생각이나 느낌을 까닭과 함께 썼는가"]},"explanation":["앞면.","왼쪽 면.","오른쪽 면."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#10','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',4,'essay','teacher','친구가 같은 책을 읽고 나와 다른 느낌을 말했어요. 친구의 생각을 존중하면서 내 생각을 까닭과 함께 전하는 말을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C9","difficulty":4,"kind":"essay","stem":"친구가 같은 책을 읽고 나와 다른 느낌을 말했어요. 친구의 생각을 존중하면서 내 생각을 까닭과 함께 전하는 말을 써 보세요.","answer_guide":{"answer":"예: 「너는 달팽이가 답답했구나. 그럴 수 있겠다. 나는 달팽이가 멋졌어. 왜냐하면 비가 와도 편지를 끝까지 전했기 때문이야.」","scoring_points":["친구의 생각을 인정하는 말을 썼는가","내 생각을 분명히 썼는가","내 생각의 까닭을 썼는가"]},"explanation":["친구 생각 인정.","내 생각.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#1','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"안내판","correct":true},{"t":"지우개","mis":"K2-1-u6-X01"},{"t":"우산","mis":"K2-1-u6-X01"}],"explanation":["「안내판」은 무언가를 알려 주는 매체예요.","다른 두 가지는 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#2','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"줄넘기를 하면 좋은 점","correct":true},{"t":"줄넘기 줄의 색깔","mis":"K2-1-u6-X03"},{"t":"수영하는 방법","mis":"K2-1-u6-X04"}],"explanation":["제목에 글의 가장 중요한 내용이 담겨 있어요.","다른 보기는 글에 없거나 제목과 맞지 않아요.","제목을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#3','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 도윤이가 기르자고 한 것은 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이가 기르자고 한 것은 무엇인가요?","options":[{"t":"물고기","correct":true},{"t":"강낭콩","mis":"K2-1-u6-X08"},{"t":"달팽이","mis":"K2-1-u6-X08"}],"explanation":["도윤이는 「물고기를 기르자.」라고 했어요.","다른 보기는 다른 친구의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#4','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C10',1,'mc','auto','토박이말 「까치밥」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":4,"concept":"K2-1-u6-C10","difficulty":1,"kind":"mc","stem":"토박이말 「까치밥」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"새가 먹으라고 나무에 남겨 둔 감","correct":true},{"t":"까치가 지은 밥","mis":"K2-1-u6-X15"},{"t":"까치집 모양의 떡","mis":"K2-1-u6-X15"}],"explanation":["「까치밥」은 「새가 먹으라고 나무에 남겨 둔 감」을 뜻해요.","다른 보기는 뜻이 다르거나 글자 모양만 보고 짐작한 것이에요.","토박이말이 쓰이는 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#5','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":5,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"줄넘기","correct":true},{"t":"마당","mis":"K2-1-u6-X05"},{"t":"다리","mis":"K2-1-u6-X05"}],"explanation":["「줄넘기」가 글에 여러 번 나와요.","다른 두 낱말은 한 번씩만 나와요.","나올 때마다 세어 봐요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#6','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"그렇게 생각한 까닭","correct":true},{"t":"큰 소리로 우기기","mis":"K2-1-u6-X11"},{"t":"친구 말 무시하기","mis":"K2-1-u6-X11"}],"explanation":["까닭을 함께 말하면 생각이 잘 전해져요.","다른 보기는 생각을 나누는 데 방해가 돼요.","생각과 까닭을 예의 바르게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#7','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C9',1,'mc','auto','책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"책 제목","correct":true},{"t":"전화번호","mis":"K2-1-u6-X13"},{"t":"비밀번호","mis":"K2-1-u6-X13"}],"explanation":["「책 제목」은 책을 소개하는 데 도움이 돼요.","다른 보기는 책과 상관없어요.","「이 내용이 책을 알려 주나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#8','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C2',1,'ox','auto','매체를 보고 든 생각을 말할 때 까닭을 함께 말하면 더 잘 전해져요.',ARRAY['K2-1-u6-X10']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"매체를 보고 든 생각을 말할 때 까닭을 함께 말하면 더 잘 전해져요.","answer":"O","reason_options":[{"t":"듣는 사람이 왜 그렇게 생각했는지 알 수 있으니까","correct":true},{"t":"까닭은 말하지 않아야 더 멋지니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["까닭을 들으면 생각을 더 잘 이해해요.","생각과 까닭을 함께 말해요.","「왜냐하면 ~거든」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#9','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"안내판","r":"이용 방법과 주의할 점"},{"l":"광고","r":"전하고 싶은 말"},{"l":"이야기책","r":"인물의 이야기"}],"mis":"K2-1-u6-X02","explanation":["「안내판」 — 이용 방법과 주의할 점","「광고」 — 전하고 싶은 말","「이야기책」 — 인물의 이야기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#10','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기를 하면 몸이 튼튼해집니다.","correct":true},{"t":"팔과 다리를 함께 움직이기 때문입니다.","mis":"K2-1-u6-X06"},{"t":"긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","mis":"K2-1-u6-X07"}],"explanation":["첫째 부분은 몸이 튼튼해진다는 것이 가장 하고 싶은 말이에요.","예를 들거나 까닭을 덧붙인 문장은 중심 문장이 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#11','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 하린이가 강낭콩을 기르자고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],false,'{"seq":11,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하린이가 강낭콩을 기르자고 한 까닭은 무엇인가요?","options":[{"t":"싹이 트고 자라는 모습을 날마다 볼 수 있어서","correct":true},{"t":"먹이만 주면 되어 돌보기 쉬워서","mis":"K2-1-u6-X08"},{"t":"강낭콩이 초록색이어서","mis":"K2-1-u6-X09"}],"explanation":["하린이는 자라는 모습을 볼 수 있다고 했어요.","다른 친구의 까닭이나 까닭이 아닌 말과 헷갈리지 않아요.","생각 뒤의 좋은 점을 찾아요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#12','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.","pairs":[{"l":"도윤","r":"물고기를 기르자"},{"l":"하린","r":"강낭콩을 기르자"},{"l":"지후","r":"달팽이를 기르자"}],"mis":"K2-1-u6-X08","explanation":["도윤 — 물고기를 기르자","하린 — 강낭콩을 기르자","지후 — 달팽이를 기르자"],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#13','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C10',2,'match','auto','토박이말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u6-C10","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"까치밥","r":"새가 먹으라고 남긴 감"},{"l":"벗","r":"친하게 사귀는 사람"},{"l":"여우비","r":"해 난 날 잠깐 오는 비"}],"mis":"K2-1-u6-X15","explanation":["「까치밥」 — 새가 먹으라고 남긴 감","「벗」 — 친하게 사귀는 사람","「여우비」 — 해 난 날 잠깐 오는 비"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#14','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',2,'mc','auto','「교실 생물로 무엇을 기를까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":14,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"「교실 생물로 무엇을 기를까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 강낭콩이 좋다고 생각해. 왜냐하면 날마다 자라는 걸 볼 수 있거든.」","correct":true},{"t":"「강낭콩. 그냥.」","mis":"K2-1-u6-X10"},{"t":"「강낭콩 아니면 안 기를 거야!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","까닭 없이 말하거나 우기는 말은 생각을 잘 전하지 못해요.","「나는 ~라고 생각해. 왜냐하면 ~거든.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#15','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C7',2,'ox','auto','대화를 읽고 답해 보세요. 「강낭콩을 기르자.」는 하린이가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C7","difficulty":2,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「강낭콩을 기르자.」는 하린이가 말한 까닭이에요.","answer":"X","reason_options":[{"t":"「기르자」는 생각이고, 까닭은 「자라는 모습을 볼 수 있다」니까","correct":true},{"t":"「~하자」로 끝나는 말은 모두 까닭이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["「강낭콩을 기르자.」는 하린이의 생각이에요.","까닭은 생각을 뒷받침하는 좋은 점이나 옳은 점이에요.","「왜?」에 대답이 되는지 넣어 봐요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#16','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C2',2,'sa','auto','「나는 이 안내판이 꼭 필요하다고 생각해. (     ) 놀이터에서 다치지 않게 도와주거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C2","difficulty":2,"kind":"sa","stem":"「나는 이 안내판이 꼭 필요하다고 생각해. (     ) 놀이터에서 다치지 않게 도와주거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.","answer":["왜냐하면"],"explanation":["까닭을 말할 때는 「왜냐하면」으로 시작해요.","「왜냐하면」 뒤에 그렇게 생각한 까닭을 말해요.","생각 → 왜냐하면 → 까닭 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#17','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X16']::text[],false,'{"seq":17,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"도윤 — 「줄넘기는 마당에서만 할 수 있다.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"하린 — 「줄넘기를 하면 몸이 튼튼해진다.」","mis":"K2-1-u6-X16"},{"t":"지후 — 「줄넘기는 친구와 즐겁게 할 수 있다.」","mis":"K2-1-u6-X16"}],"explanation":["글에는 줄넘기를 어디서나 할 수 있다고 했어요.","중요한 내용은 글 전체를 보고 정리해요.","다른 두 친구는 바르게 정리했어요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#18','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C3',3,'mc','auto','「꿀벌은 꽃에서 꿀을 모읍니다. 꽃가루를 옮겨 열매가 열리도록 돕습니다. 힘을 모아 벌집을 짓습니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":18,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「꿀벌은 꽃에서 꿀을 모읍니다. 꽃가루를 옮겨 열매가 열리도록 돕습니다. 힘을 모아 벌집을 짓습니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"꿀벌이 하는 일","correct":true},{"t":"꽃의 색깔","mis":"K2-1-u6-X04"},{"t":"맛있는 꿀 요리","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 꿀벌이 하는 일을 알려 줘요.","다른 보기는 글의 내용과 어울리지 않아요.","글 전체가 무엇을 알려 주는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#19','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],false,'{"seq":19,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「지후는 돌보기 쉬워서 달팽이를 기르자고 했어.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"채원 — 「하린이는 자라는 모습을 보려고 강낭콩을 기르자고 했어.」","mis":"K2-1-u6-X16"},{"t":"건우 — 「도윤이는 돌보기 쉬워서 물고기를 기르자고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「돌보기 쉬워서」는 도윤이가 말한 까닭이에요.","인물을 뒤바꾸지 않도록 말한 사람을 확인해요.","다른 두 친구는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#20','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',3,'error','auto','「교실 생물로 무엇을 기를까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":20,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「교실 생물로 무엇을 기를까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"민지 — 「물고기라니, 네 생각은 틀렸어.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"지후 — 「나는 달팽이가 좋아. 너는 왜 물고기가 좋아?」","mis":"K2-1-u6-X16"},{"t":"윤서 — 「물고기도 좋겠다. 나는 강낭콩이 더 좋지만.」","mis":"K2-1-u6-X16"}],"explanation":["다른 생각을 틀렸다고 하면 안 돼요.","생각이 달라도 친구의 까닭을 들어 봐요.","다른 두 친구는 예의 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#21','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C9',3,'mc','auto','상자를 읽고 답해 보세요. 수빈이가 이 책을 읽고 든 생각과 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X13']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이가 이 책을 읽고 든 생각과 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"달팽이가 멋지다 — 비가 와도 포기하지 않아서","correct":true},{"t":"달팽이가 답답하다 — 너무 느려서","mis":"K2-1-u6-X07"},{"t":"달팽이가 멋지다 — 수빈이 집에 달팽이가 있어서","mis":"K2-1-u6-X13"}],"explanation":["오른쪽 면에 생각과 까닭이 함께 쓰여 있어요.","다른 보기는 상자의 내용과 맞지 않거나 책과 상관없어요.","상자의 면을 돌려 가며 살펴요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#22','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":22,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"마당","correct":true},{"t":"줄넘기","mis":"K2-1-u6-X16"},{"t":"좋은 점","mis":"K2-1-u6-X16"}],"explanation":["「마당」은 한 번만 나와요.","다른 두 낱말은 제목에 있거나 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#23','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 몸이 튼튼해진다 · 친구와 즐겁게 할 수 있다 · 어디서나 할 수 있다 → 줄넘기는 몸을 튼튼하게 하고, 친구와 즐겁게, 어디서나 할 수 있는 좋은 운동이다.","scoring_points":["중심 문장을 빠짐없이 찾았는가","예나 까닭을 덧붙인 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["중심 문장 찾기.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#24','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C6',4,'essay','teacher','대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 도윤 — 물고기, 돌보기 쉬워서. 하린 — 강낭콩, 자라는 모습을 볼 수 있어서. 나는 하린이 생각에 찬성해요. 왜냐하면 날마다 키를 재며 관찰할 수 있기 때문이에요.","scoring_points":["두 인물의 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가","찬성하는 생각과 내 까닭을 썼는가"]},"explanation":["인물의 생각.","짝이 되는 까닭.","내 생각과 까닭."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#25','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',4,'essay','teacher','「쉬는 시간을 조금 더 늘리면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"「쉬는 시간을 조금 더 늘리면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.","answer_guide":{"answer":"예: 나는 쉬는 시간을 조금 늘리면 좋겠다고 생각해. 왜냐하면 화장실도 여유 있게 다녀올 수 있고, 다음 시간 준비도 할 수 있기 때문이야.","scoring_points":["내 생각을 분명히 썼는가","생각을 뒷받침하는 까닭을 두 가지 썼는가","알맞은 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","까닭 두 가지.","예의 바른 꼴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#1','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"광고","correct":true},{"t":"의자","mis":"K2-1-u6-X01"},{"t":"신발","mis":"K2-1-u6-X01"}],"explanation":["「광고」는 무언가를 알려 주는 매체예요.","다른 두 가지는 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#2','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"꿀벌이 하는 일","correct":true},{"t":"꿀벌의 색깔","mis":"K2-1-u6-X03"},{"t":"꽃 파는 가게","mis":"K2-1-u6-X04"}],"explanation":["제목에 글의 가장 중요한 내용이 담겨 있어요.","다른 보기는 글에 없거나 제목과 맞지 않아요.","제목을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#3','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 서아가 하자고 한 놀이는 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 서아가 하자고 한 놀이는 무엇인가요?","options":[{"t":"피구","correct":true},{"t":"줄넘기","mis":"K2-1-u6-X08"},{"t":"숨바꼭질","mis":"K2-1-u6-X08"}],"explanation":["서아는 「피구를 하자.」라고 했어요.","다른 보기는 다른 친구의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#4','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C10',1,'mc','auto','토박이말 「벗」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":4,"concept":"K2-1-u6-C10","difficulty":1,"kind":"mc","stem":"토박이말 「벗」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"친하게 사귀는 사람","correct":true},{"t":"신발을 벗는 일","mis":"K2-1-u6-X15"},{"t":"처음 만난 사람","mis":"K2-1-u6-X15"}],"explanation":["「벗」은 「친하게 사귀는 사람」을 뜻해요.","다른 보기는 뜻이 다르거나 글자 모양만 보고 짐작한 것이에요.","토박이말이 쓰이는 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#5','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":5,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"꿀벌","correct":true},{"t":"열매","mis":"K2-1-u6-X05"},{"t":"벌집","mis":"K2-1-u6-X05"}],"explanation":["「꿀벌」이 글에 여러 번 나와요.","다른 두 낱말은 한 번씩만 나와요.","나올 때마다 세어 봐요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#6','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"예의 바른 말","correct":true},{"t":"친구 말 끊기","mis":"K2-1-u6-X11"},{"t":"화난 목소리","mis":"K2-1-u6-X11"}],"explanation":["예의 바르게 말하면 친구도 잘 들어 줘요.","다른 보기는 생각을 나누는 데 방해가 돼요.","생각과 까닭을 예의 바르게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#7','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C9',1,'mc','auto','책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"기억에 남는 문장","correct":true},{"t":"시험 점수","mis":"K2-1-u6-X13"},{"t":"내일 날씨","mis":"K2-1-u6-X13"}],"explanation":["「기억에 남는 문장」은 책을 소개하는 데 도움이 돼요.","다른 보기는 책과 상관없어요.","「이 내용이 책을 알려 주나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#8','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C2',1,'ox','auto','「이 광고는 좋아.」라고만 말해도 내 생각이 충분히 전해져요.',ARRAY['K2-1-u6-X10']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"「이 광고는 좋아.」라고만 말해도 내 생각이 충분히 전해져요.","answer":"X","reason_options":[{"t":"왜 좋은지 까닭을 덧붙여야 잘 전해지니까","correct":true},{"t":"생각은 짧을수록 언제나 잘 전해지니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["「좋아.」만으로는 왜 좋은지 알 수 없어요.","생각과 까닭을 함께 말해요.","「왜냐하면 ~거든」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#9','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"식단표","r":"먹을 음식"},{"l":"일기 예보","r":"날씨"},{"l":"알림장","r":"준비물과 숙제"}],"mis":"K2-1-u6-X02","explanation":["「식단표」 — 먹을 음식","「일기 예보」 — 날씨","「알림장」 — 준비물과 숙제"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#10','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 둘째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 둘째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기는 친구와 함께 즐겁게 할 수 있습니다.","correct":true},{"t":"긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","mis":"K2-1-u6-X06"},{"t":"줄넘기를 하면 몸이 튼튼해집니다.","mis":"K2-1-u6-X07"}],"explanation":["둘째 부분은 친구와 즐겁게 할 수 있다는 것이 가장 하고 싶은 말이에요.","예를 들거나 까닭을 덧붙인 문장은 중심 문장이 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#11','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 민호가 줄넘기를 하자고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],false,'{"seq":11,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 민호가 줄넘기를 하자고 한 까닭은 무엇인가요?","options":[{"t":"넘은 횟수를 세면서 실력을 키울 수 있어서","correct":true},{"t":"규칙이 쉬워서 누구나 할 수 있어서","mis":"K2-1-u6-X08"},{"t":"민호의 줄넘기 줄이 새것이어서","mis":"K2-1-u6-X09"}],"explanation":["민호는 실력을 키울 수 있다고 했어요.","다른 친구의 까닭이나 까닭이 아닌 말과 헷갈리지 않아요.","생각 뒤의 좋은 점을 찾아요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#12','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.","pairs":[{"l":"서아","r":"피구를 하자"},{"l":"민호","r":"줄넘기를 하자"},{"l":"예린","r":"숨바꼭질을 하자"}],"mis":"K2-1-u6-X08","explanation":["서아 — 피구를 하자","민호 — 줄넘기를 하자","예린 — 숨바꼭질을 하자"],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#13','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C10',2,'match','auto','토박이말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u6-C10","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"단비","r":"꼭 필요할 때 알맞게 오는 비"},{"l":"함박눈","r":"굵고 탐스럽게 내리는 눈"},{"l":"나들이","r":"가까운 곳에 잠깐 다녀오는 일"}],"mis":"K2-1-u6-X15","explanation":["「단비」 — 꼭 필요할 때 알맞게 오는 비","「함박눈」 — 굵고 탐스럽게 내리는 눈","「나들이」 — 가까운 곳에 잠깐 다녀오는 일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#14','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',2,'mc','auto','「체육 시간에 무슨 놀이를 할까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":14,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"「체육 시간에 무슨 놀이를 할까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 피구가 좋다고 생각해. 왜냐하면 모두 함께 뛸 수 있거든.」","correct":true},{"t":"「피구 하고 싶어. 끝.」","mis":"K2-1-u6-X10"},{"t":"「피구 싫은 사람은 빠져!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","까닭 없이 말하거나 우기는 말은 생각을 잘 전하지 못해요.","「나는 ~라고 생각해. 왜냐하면 ~거든.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#15','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C7',2,'ox','auto','대화를 읽고 답해 보세요. 「규칙이 쉬워서 누구나 할 수 있으니까.」는 예린이가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C7","difficulty":2,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「규칙이 쉬워서 누구나 할 수 있으니까.」는 예린이가 말한 까닭이에요.","answer":"O","reason_options":[{"t":"숨바꼭질을 하자는 생각을 뒷받침하는 말이니까","correct":true},{"t":"예린이가 하고 싶은 놀이 이름이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["이 말은 숨바꼭질을 하자는 생각의 까닭이에요.","까닭은 생각을 뒷받침하는 좋은 점이나 옳은 점이에요.","「왜?」에 대답이 되는지 넣어 봐요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#16','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C2',2,'sa','auto','「나는 도서관 책 잔치에 가 보고 싶어. (     ) 책을 읽으면 책갈피도 받을 수 있거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C2","difficulty":2,"kind":"sa","stem":"「나는 도서관 책 잔치에 가 보고 싶어. (     ) 책을 읽으면 책갈피도 받을 수 있거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.","answer":["왜냐하면"],"explanation":["까닭을 말할 때는 「왜냐하면」으로 시작해요.","「왜냐하면」 뒤에 그렇게 생각한 까닭을 말해요.","생각 → 왜냐하면 → 까닭 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#17','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X16']::text[],false,'{"seq":17,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"예린 — 「꿀벌은 꽃잎을 먹고 산다.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"민호 — 「꿀벌은 꽃에서 꿀을 모은다.」","mis":"K2-1-u6-X16"},{"t":"서아 — 「꿀벌은 함께 벌집을 짓는다.」","mis":"K2-1-u6-X16"}],"explanation":["꽃잎을 먹는다는 말은 글에 없어요.","중요한 내용은 글 전체를 보고 정리해요.","다른 두 친구는 바르게 정리했어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#18','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C3',3,'mc','auto','「강아지는 냄새를 잘 맡습니다. 강아지는 주인을 반기며 꼬리를 흔듭니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":18,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「강아지는 냄새를 잘 맡습니다. 강아지는 주인을 반기며 꼬리를 흔듭니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"강아지의 특징","correct":true},{"t":"고양이 기르는 법","mis":"K2-1-u6-X04"},{"t":"맛있는 간식","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 강아지에 대해 알려 줘요.","다른 보기는 글의 내용과 어울리지 않아요.","글 전체가 무엇을 알려 주는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#19','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],false,'{"seq":19,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수빈 — 「서아는 규칙이 쉬워서 피구를 하자고 했어.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"시우 — 「민호는 실력을 키우려고 줄넘기를 하자고 했어.」","mis":"K2-1-u6-X16"},{"t":"다은 — 「예린이는 규칙이 쉬워서 숨바꼭질을 하자고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「규칙이 쉬워서」는 예린이가 말한 까닭이에요.","인물을 뒤바꾸지 않도록 말한 사람을 확인해요.","다른 두 친구는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#20','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',3,'error','auto','「체육 시간에 무슨 놀이를 할까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":20,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「체육 시간에 무슨 놀이를 할까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"준우 — 「숨바꼭질은 시시해. 그런 걸 고르는 건 이상해.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"예린 — 「나는 피구가 좋은데, 숨바꼭질 까닭도 들어 볼게.」","mis":"K2-1-u6-X16"},{"t":"하린 — 「숨바꼭질도 재미있겠다. 나는 줄넘기가 좋아.」","mis":"K2-1-u6-X16"}],"explanation":["친구가 고른 것을 이상하다고 하면 안 돼요.","생각이 달라도 친구의 까닭을 들어 봐요.","다른 두 친구는 예의 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#21','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C9',3,'mc','auto','상자를 읽고 답해 보세요. 기억에 남는 문장이 쓰인 곳과 그 문장을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X14','K2-1-u6-X13']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"상자를 읽고 답해 보세요. 기억에 남는 문장이 쓰인 곳과 그 문장을 바르게 말한 것은 어느 것인가요?","options":[{"t":"왼쪽 면 — 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","correct":true},{"t":"앞면 — 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","mis":"K2-1-u6-X14"},{"t":"왼쪽 면 — 수빈이의 받아쓰기 점수","mis":"K2-1-u6-X13"}],"explanation":["왼쪽 면에 기억에 남는 문장을 썼어요.","다른 보기는 상자의 내용과 맞지 않거나 책과 상관없어요.","상자의 면을 돌려 가며 살펴요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#22','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":22,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"열매","correct":true},{"t":"꿀벌","mis":"K2-1-u6-X16"},{"t":"하는 일","mis":"K2-1-u6-X16"}],"explanation":["「열매」는 한 번만 나와요.","다른 두 낱말은 제목에 있거나 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#23','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 꿀을 모은다 · 꽃가루를 옮겨 열매를 돕는다 · 함께 벌집을 짓는다 → 꿀벌은 꿀을 모으고, 열매가 열리게 돕고, 힘을 모아 벌집을 짓는다.","scoring_points":["중심 문장을 빠짐없이 찾았는가","예나 까닭을 덧붙인 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["중심 문장 찾기.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#24','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C6',4,'essay','teacher','대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 서아 — 피구, 모두가 함께 뛸 수 있어서. 예린 — 숨바꼭질, 규칙이 쉬워서. 나는 서아 생각에 찬성해요. 왜냐하면 반 친구 모두가 함께 놀 수 있기 때문이에요.","scoring_points":["두 인물의 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가","찬성하는 생각과 내 까닭을 썼는가"]},"explanation":["인물의 생각.","짝이 되는 까닭.","내 생각과 까닭."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#25','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',4,'essay','teacher','「학급 문고에 어떤 책을 더 두면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"「학급 문고에 어떤 책을 더 두면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.","answer_guide":{"answer":"예: 나는 과학 그림책을 더 두면 좋겠다고 생각해. 왜냐하면 궁금한 것을 바로 찾아볼 수 있고, 그림이 많아 누구나 쉽게 읽을 수 있기 때문이야.","scoring_points":["내 생각을 분명히 썼는가","생각을 뒷받침하는 까닭을 두 가지 썼는가","알맞은 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","까닭 두 가지.","예의 바른 꼴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#1','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"알림장","correct":true},{"t":"필통","mis":"K2-1-u6-X01"},{"t":"컵","mis":"K2-1-u6-X01"}],"explanation":["「알림장」은 무언가를 알려 주는 매체예요.","다른 두 가지는 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#2','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"손을 깨끗이 씻는 일","correct":true},{"t":"비누의 냄새","mis":"K2-1-u6-X03"},{"t":"발을 씻는 방법","mis":"K2-1-u6-X04"}],"explanation":["제목에 글의 가장 중요한 내용이 담겨 있어요.","다른 보기는 글에 없거나 제목과 맞지 않아요.","제목을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#3','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 하늘이가 가고 싶어 한 곳은 어디인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하늘이가 가고 싶어 한 곳은 어디인가요?","options":[{"t":"바닷가","correct":true},{"t":"동물원","mis":"K2-1-u6-X08"},{"t":"과학관","mis":"K2-1-u6-X08"}],"explanation":["하늘이는 바닷가에 가고 싶다고 했어요.","다른 보기는 다른 친구의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#4','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C10',1,'mc','auto','토박이말 「여우비」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":4,"concept":"K2-1-u6-C10","difficulty":1,"kind":"mc","stem":"토박이말 「여우비」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"해가 난 날 잠깐 오는 비","correct":true},{"t":"여우가 오는 날","mis":"K2-1-u6-X15"},{"t":"밤새 많이 오는 비","mis":"K2-1-u6-X15"}],"explanation":["「여우비」는 「해가 난 날 잠깐 오는 비」를 뜻해요.","다른 보기는 뜻이 다르거나 글자 모양만 보고 짐작한 것이에요.","토박이말이 쓰이는 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#5','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":5,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"손","correct":true},{"t":"감기","mis":"K2-1-u6-X05"},{"t":"거품","mis":"K2-1-u6-X05"}],"explanation":["「손」이 글에 여러 번 나와요.","다른 두 낱말은 한 번씩만 나와요.","나올 때마다 세어 봐요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#6','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11','K2-1-u6-X10']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각","correct":true},{"t":"친구 놀리기","mis":"K2-1-u6-X11"},{"t":"「그냥」이라고만 하기","mis":"K2-1-u6-X10"}],"explanation":["무엇을 생각하는지 분명히 말해요.","다른 보기는 생각을 나누는 데 방해가 돼요.","생각과 까닭을 예의 바르게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#7','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C9',1,'mc','auto','책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"인상 깊은 장면","correct":true},{"t":"집 주소","mis":"K2-1-u6-X13"},{"t":"게임 이름","mis":"K2-1-u6-X13"}],"explanation":["「인상 깊은 장면」은 책을 소개하는 데 도움이 돼요.","다른 보기는 책과 상관없어요.","「이 내용이 책을 알려 주나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#8','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C2',1,'ox','auto','「왜냐하면」 뒤에는 그렇게 생각한 까닭을 말해요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"「왜냐하면」 뒤에는 그렇게 생각한 까닭을 말해요.","answer":"O","reason_options":[{"t":"「왜냐하면」은 까닭을 이끄는 말이니까","correct":true},{"t":"「왜냐하면」 뒤에는 인사말을 하니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["「왜냐하면 ~거든」으로 까닭을 말해요.","생각과 까닭을 함께 말해요.","「왜냐하면 ~거든」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#9','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"표지판","r":"길과 지켜야 할 일"},{"l":"달력","r":"날짜"},{"l":"그림책","r":"그림과 이야기"}],"mis":"K2-1-u6-X02","explanation":["「표지판」 — 길과 지켜야 할 일","「달력」 — 날짜","「그림책」 — 그림과 이야기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#10','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"손을 깨끗이 씻으면 감기를 막을 수 있습니다.","correct":true},{"t":"손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","mis":"K2-1-u6-X06"},{"t":"손바닥과 손등, 손가락 사이까지 문지릅니다.","mis":"K2-1-u6-X07"}],"explanation":["첫째 부분은 손을 씻으면 감기를 막는다는 것이 가장 하고 싶은 말이에요.","예를 들거나 까닭을 덧붙인 문장은 중심 문장이 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#11','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 지호가 과학관에 가고 싶은 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],false,'{"seq":11,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 지호가 과학관에 가고 싶은 까닭은 무엇인가요?","options":[{"t":"여러 가지 실험을 해 볼 수 있어서","correct":true},{"t":"책에서만 본 동물을 볼 수 있어서","mis":"K2-1-u6-X08"},{"t":"과학관 지붕이 둥글어서","mis":"K2-1-u6-X09"}],"explanation":["지호는 실험을 해 볼 수 있다고 했어요.","다른 친구의 까닭이나 까닭이 아닌 말과 헷갈리지 않아요.","생각 뒤의 좋은 점을 찾아요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#12','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.","pairs":[{"l":"소율","r":"동물원에 가고 싶다"},{"l":"지호","r":"과학관에 가고 싶다"},{"l":"하늘","r":"바닷가에 가고 싶다"}],"mis":"K2-1-u6-X08","explanation":["소율 — 동물원에 가고 싶다","지호 — 과학관에 가고 싶다","하늘 — 바닷가에 가고 싶다"],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#13','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C10',2,'match','auto','토박이말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u6-C10","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"벗","r":"친하게 사귀는 사람"},{"l":"단비","r":"꼭 필요할 때 알맞게 오는 비"},{"l":"까치밥","r":"새가 먹으라고 남긴 감"}],"mis":"K2-1-u6-X15","explanation":["「벗」 — 친하게 사귀는 사람","「단비」 — 꼭 필요할 때 알맞게 오는 비","「까치밥」 — 새가 먹으라고 남긴 감"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#14','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',2,'mc','auto','「연못 반장으로 누가 좋을까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":14,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"「연못 반장으로 누가 좋을까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 거북이 좋다고 생각해. 왜냐하면 차분하게 꼼꼼히 살필 수 있거든.」","correct":true},{"t":"「거북이 좋아. 이유는 없어.」","mis":"K2-1-u6-X10"},{"t":"「거북 말고 고르는 애는 이상해!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","까닭 없이 말하거나 우기는 말은 생각을 잘 전하지 못해요.","「나는 ~라고 생각해. 왜냐하면 ~거든.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#15','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',2,'ox','auto','대화를 읽고 답해 보세요. 「과학관에 가고 싶어.」는 지호가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C7","difficulty":2,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「과학관에 가고 싶어.」는 지호가 말한 까닭이에요.","answer":"X","reason_options":[{"t":"이 말은 생각이고, 까닭은 「실험을 해 볼 수 있어서」니까","correct":true},{"t":"「가고 싶어」는 언제나 까닭이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["「과학관에 가고 싶어.」는 지호의 생각이에요.","까닭은 생각을 뒷받침하는 좋은 점이나 옳은 점이에요.","「왜?」에 대답이 되는지 넣어 봐요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#16','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C2',2,'sa','auto','「나는 손 씻기 글이 도움이 되었어. (     ) 손을 씻어야 할 때를 새로 알았거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C2","difficulty":2,"kind":"sa","stem":"「나는 손 씻기 글이 도움이 되었어. (     ) 손을 씻어야 할 때를 새로 알았거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.","answer":["왜냐하면"],"explanation":["까닭을 말할 때는 「왜냐하면」으로 시작해요.","「왜냐하면」 뒤에 그렇게 생각한 까닭을 말해요.","생각 → 왜냐하면 → 까닭 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#17','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X16']::text[],false,'{"seq":17,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"태민 — 「이 글의 중요한 내용은 거품이 하얗다는 것이다.」","correct":true,"mis_target":"K2-1-u6-X03"},{"t":"아린 — 「손을 씻으면 감기를 막을 수 있다.」","mis":"K2-1-u6-X16"},{"t":"시우 — 「밥 먹기 전에는 꼭 손을 씻는다.」","mis":"K2-1-u6-X16"}],"explanation":["거품 색깔은 글에 없고 중요한 내용도 아니에요.","중요한 내용은 글 전체를 보고 정리해요.","다른 두 친구는 바르게 정리했어요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#18','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C3',3,'mc','auto','「해바라기는 해를 따라 고개를 돌립니다. 해바라기 씨는 먹을 수 있습니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":18,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「해바라기는 해를 따라 고개를 돌립니다. 해바라기 씨는 먹을 수 있습니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"해바라기에 대해 알아봐요","correct":true},{"t":"장미꽃 키우기","mis":"K2-1-u6-X04"},{"t":"여름 방학 계획","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 해바라기에 대해 알려 줘요.","다른 보기는 글의 내용과 어울리지 않아요.","글 전체가 무엇을 알려 주는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#19','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],false,'{"seq":19,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「소율이는 실험을 하려고 동물원에 가고 싶대.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"지안 — 「지호는 실험을 하려고 과학관에 가고 싶대.」","mis":"K2-1-u6-X16"},{"t":"현우 — 「하늘이는 조개를 주우려고 바닷가에 가고 싶대.」","mis":"K2-1-u6-X16"}],"explanation":["「실험」은 지호가 말한 까닭이에요.","인물을 뒤바꾸지 않도록 말한 사람을 확인해요.","다른 두 친구는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#20','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',3,'error','auto','「연못 반장으로 누가 좋을까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":20,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「연못 반장으로 누가 좋을까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"태민 — 「거북을 고른 애들은 생각이 없어.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"다은 — 「나는 오리가 좋아. 거북 까닭도 일리가 있네.」","mis":"K2-1-u6-X16"},{"t":"민호 — 「나는 개구리가 좋아. 너는 왜 거북이야?」","mis":"K2-1-u6-X16"}],"explanation":["친구를 생각이 없다고 하면 안 돼요.","생각이 달라도 친구의 까닭을 들어 봐요.","다른 두 친구는 예의 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#21','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C9',3,'mc','auto','상자를 읽고 답해 보세요. 수빈이의 상자에 더 넣으면 좋을 내용은 어느 것인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X13']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이의 상자에 더 넣으면 좋을 내용은 어느 것인가요?","options":[{"t":"이 책을 권하고 싶은 친구와 그 까닭","correct":true},{"t":"달팽이 껍데기를 깨는 방법","mis":"K2-1-u6-X07"},{"t":"수빈이의 집 주소","mis":"K2-1-u6-X13"}],"explanation":["책 소개를 풍성하게 하는 내용이 알맞아요.","다른 보기는 상자의 내용과 맞지 않거나 책과 상관없어요.","상자의 면을 돌려 가며 살펴요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#22','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":22,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"거품","correct":true},{"t":"손","mis":"K2-1-u6-X16"},{"t":"씻어요","mis":"K2-1-u6-X16"}],"explanation":["「거품」은 한 번만 나와요.","다른 두 낱말은 제목에 있거나 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#23','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 손을 씻으면 감기를 막는다 · 비누로 구석구석 씻는다 · 씻어야 할 때를 지킨다 → 감기를 막으려면 비누로 구석구석, 씻어야 할 때 꼭 손을 씻자.","scoring_points":["중심 문장을 빠짐없이 찾았는가","예나 까닭을 덧붙인 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["중심 문장 찾기.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#24','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C6',4,'essay','teacher','대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 소율 — 동물원, 동물을 직접 볼 수 있어서. 지호 — 과학관, 실험을 해 볼 수 있어서. 나는 지호 생각에 찬성해요. 왜냐하면 직접 해 보면 더 오래 기억에 남기 때문이에요.","scoring_points":["두 인물의 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가","찬성하는 생각과 내 까닭을 썼는가"]},"explanation":["인물의 생각.","짝이 되는 까닭.","내 생각과 까닭."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#25','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',4,'essay','teacher','「교실 생물로 무엇을 기르면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"「교실 생물로 무엇을 기르면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.","answer_guide":{"answer":"예: 나는 강낭콩을 기르면 좋겠다고 생각해. 왜냐하면 자라는 모습을 날마다 볼 수 있고, 돌보는 방법도 어렵지 않기 때문이야.","scoring_points":["내 생각을 분명히 썼는가","생각을 뒷받침하는 까닭을 두 가지 썼는가","알맞은 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","까닭 두 가지.","예의 바른 꼴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#1','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"일기 예보","correct":true},{"t":"공","mis":"K2-1-u6-X01"},{"t":"숟가락","mis":"K2-1-u6-X01"}],"explanation":["「일기 예보」는 무언가를 알려 주는 매체예요.","다른 두 가지는 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#2','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"물을 아껴 쓰는 방법","correct":true},{"t":"물의 색깔","mis":"K2-1-u6-X03"},{"t":"수영을 잘하는 방법","mis":"K2-1-u6-X04"}],"explanation":["제목에 글의 가장 중요한 내용이 담겨 있어요.","다른 보기는 글에 없거나 제목과 맞지 않아요.","제목을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#3','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 지후가 기르자고 한 것은 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 지후가 기르자고 한 것은 무엇인가요?","options":[{"t":"달팽이","correct":true},{"t":"물고기","mis":"K2-1-u6-X08"},{"t":"강낭콩","mis":"K2-1-u6-X08"}],"explanation":["지후는 「달팽이를 기르자.」라고 했어요.","다른 보기는 다른 친구의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#4','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C10',1,'mc','auto','토박이말 「함박눈」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":4,"concept":"K2-1-u6-C10","difficulty":1,"kind":"mc","stem":"토박이말 「함박눈」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"굵고 탐스럽게 내리는 눈","correct":true},{"t":"함박꽃이 피는 날","mis":"K2-1-u6-X15"},{"t":"아주 가늘게 내리는 눈","mis":"K2-1-u6-X15"}],"explanation":["「함박눈」은 「굵고 탐스럽게 내리는 눈」을 뜻해요.","다른 보기는 뜻이 다르거나 글자 모양만 보고 짐작한 것이에요.","토박이말이 쓰이는 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#5','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":5,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"물","correct":true},{"t":"컵","mis":"K2-1-u6-X05"},{"t":"샤워","mis":"K2-1-u6-X05"}],"explanation":["「물」이 글에 여러 번 나와요.","다른 두 낱말은 한 번씩만 나와요.","나올 때마다 세어 봐요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#6','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11','K2-1-u6-X12']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구의 생각도 들어 보기","correct":true},{"t":"내 말만 하기","mis":"K2-1-u6-X11"},{"t":"다른 생각은 틀렸다고 하기","mis":"K2-1-u6-X12"}],"explanation":["친구의 생각을 들으면 서로 이해할 수 있어요.","다른 보기는 생각을 나누는 데 방해가 돼요.","생각과 까닭을 예의 바르게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#7','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C9',1,'mc','auto','책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 든 느낌","correct":true},{"t":"받아쓰기 점수","mis":"K2-1-u6-X13"},{"t":"좋아하는 반찬","mis":"K2-1-u6-X13"}],"explanation":["「읽고 든 느낌」은 책을 소개하는 데 도움이 돼요.","다른 보기는 책과 상관없어요.","「이 내용이 책을 알려 주나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#8','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C2',1,'ox','auto','생각을 말할 때 「그냥」이라고 하면 까닭이 잘 드러나요.',ARRAY['K2-1-u6-X10']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"생각을 말할 때 「그냥」이라고 하면 까닭이 잘 드러나요.","answer":"X","reason_options":[{"t":"「그냥」에는 까닭이 담겨 있지 않으니까","correct":true},{"t":"「그냥」은 가장 좋은 까닭이니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["「그냥」 대신 좋은 점이나 옳은 점을 말해요.","생각과 까닭을 함께 말해요.","「왜냐하면 ~거든」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#9','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"안내판","r":"이용 방법과 주의할 점"},{"l":"식단표","r":"먹을 음식"},{"l":"일기 예보","r":"날씨"}],"mis":"K2-1-u6-X02","explanation":["「안내판」 — 이용 방법과 주의할 점","「식단표」 — 먹을 음식","「일기 예보」 — 날씨"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#10','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 셋째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 셋째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다.","correct":true},{"t":"운동장에서도, 집 앞 마당에서도 할 수 있습니다.","mis":"K2-1-u6-X06"},{"t":"줄넘기를 하면 몸이 튼튼해집니다.","mis":"K2-1-u6-X07"}],"explanation":["셋째 부분은 어디서나 할 수 있다는 것이 가장 하고 싶은 말이에요.","예를 들거나 까닭을 덧붙인 문장은 중심 문장이 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#11','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 지후가 달팽이를 기르자고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],false,'{"seq":11,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 지후가 달팽이를 기르자고 한 까닭은 무엇인가요?","options":[{"t":"천천히 기어가는 모습이 귀엽고 만져 볼 수 있어서","correct":true},{"t":"싹이 자라는 모습을 볼 수 있어서","mis":"K2-1-u6-X08"},{"t":"지후 집에 달팽이 그림이 있어서","mis":"K2-1-u6-X09"}],"explanation":["지후는 귀엽고 만져 볼 수 있다고 했어요.","다른 친구의 까닭이나 까닭이 아닌 말과 헷갈리지 않아요.","생각 뒤의 좋은 점을 찾아요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#12','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.","pairs":[{"l":"개구리","r":"목소리가 커서 반장이 되겠다"},{"l":"거북","r":"꼼꼼해서 반장이 되겠다"},{"l":"오리","r":"두루 살필 수 있어서 반장이 되겠다"}],"mis":"K2-1-u6-X08","explanation":["개구리 — 목소리가 커서 반장이 되겠다","거북 — 꼼꼼해서 반장이 되겠다","오리 — 두루 살필 수 있어서 반장이 되겠다"],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#13','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C10',2,'match','auto','토박이말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u6-C10","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"여우비","r":"해 난 날 잠깐 오는 비"},{"l":"나들이","r":"가까운 곳에 잠깐 다녀오는 일"},{"l":"함박눈","r":"굵고 탐스럽게 내리는 눈"}],"mis":"K2-1-u6-X15","explanation":["「여우비」 — 해 난 날 잠깐 오는 비","「나들이」 — 가까운 곳에 잠깐 다녀오는 일","「함박눈」 — 굵고 탐스럽게 내리는 눈"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#14','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C8',2,'mc','auto','「체험학습으로 어디에 갈까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":14,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"「체험학습으로 어디에 갈까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 과학관이 좋다고 생각해. 왜냐하면 직접 실험을 해 볼 수 있거든.」","correct":true},{"t":"「과학관. 그냥 좋아.」","mis":"K2-1-u6-X10"},{"t":"「무조건 과학관이야. 다른 데는 안 돼!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","까닭 없이 말하거나 우기는 말은 생각을 잘 전하지 못해요.","「나는 ~라고 생각해. 왜냐하면 ~거든.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#15','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C7',2,'ox','auto','대화를 읽고 답해 보세요. 「먹이만 잘 주면 되어서 돌보기 쉽거든.」은 도윤이가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C7","difficulty":2,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「먹이만 잘 주면 되어서 돌보기 쉽거든.」은 도윤이가 말한 까닭이에요.","answer":"O","reason_options":[{"t":"물고기를 기르자는 생각을 뒷받침하는 말이니까","correct":true},{"t":"도윤이가 기르고 싶은 동물 이름이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["이 말은 물고기를 기르자는 생각의 까닭이에요.","까닭은 생각을 뒷받침하는 좋은 점이나 옳은 점이에요.","「왜?」에 대답이 되는지 넣어 봐요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#16','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C2',2,'sa','auto','「나는 오리가 반장이 되면 좋겠어. (     ) 연못 구석구석을 살필 수 있거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C2","difficulty":2,"kind":"sa","stem":"「나는 오리가 반장이 되면 좋겠어. (     ) 연못 구석구석을 살필 수 있거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.","answer":["왜냐하면"],"explanation":["까닭을 말할 때는 「왜냐하면」으로 시작해요.","「왜냐하면」 뒤에 그렇게 생각한 까닭을 말해요.","생각 → 왜냐하면 → 까닭 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#17','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X16']::text[],false,'{"seq":17,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"로아 — 「이 글의 중요한 내용은 샤워를 짧게 하자는 것뿐이다.」","correct":true,"mis_target":"K2-1-u6-X06"},{"t":"채원 — 「컵에 물을 받아 이를 닦는다.」","mis":"K2-1-u6-X16"},{"t":"건우 — 「여러 방법으로 물을 아껴 쓰자.」","mis":"K2-1-u6-X16"}],"explanation":["샤워는 물을 아끼는 방법 가운데 하나일 뿐이에요.","중요한 내용은 글 전체를 보고 정리해요.","다른 두 친구는 바르게 정리했어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#18','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C3',3,'mc','auto','「곰은 겨울에 굴속에서 잠을 잡니다. 개구리도 땅속에서 겨울잠을 잡니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":18,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「곰은 겨울에 굴속에서 잠을 잡니다. 개구리도 땅속에서 겨울잠을 잡니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"겨울잠을 자는 동물","correct":true},{"t":"여름에 노는 동물","mis":"K2-1-u6-X04"},{"t":"동물원 가는 길","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 겨울잠을 자는 동물을 알려 줘요.","다른 보기는 글의 내용과 어울리지 않아요.","글 전체가 무엇을 알려 주는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#19','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],false,'{"seq":19,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도담 — 「거북은 목소리가 커서 반장이 되겠대.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"서윤 — 「개구리는 목소리가 커서 반장이 되겠대.」","mis":"K2-1-u6-X16"},{"t":"하준 — 「오리는 연못을 두루 살필 수 있어서 반장이 되겠대.」","mis":"K2-1-u6-X16"}],"explanation":["「목소리가 커서」는 개구리가 말한 까닭이에요.","인물을 뒤바꾸지 않도록 말한 사람을 확인해요.","다른 두 친구는 바르게 말했어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#20','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C8',3,'error','auto','「같은 책을 읽고 든 느낌」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":20,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「같은 책을 읽고 든 느낌」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"현우 — 「달팽이가 답답하다고? 네 느낌은 틀렸어.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"소율 — 「너는 답답했구나. 나는 멋졌어.」","mis":"K2-1-u6-X16"},{"t":"로아 — 「나도 처음엔 답답했는데 끝에는 멋졌어.」","mis":"K2-1-u6-X16"}],"explanation":["같은 책도 느낌이 다를 수 있어요.","생각이 달라도 친구의 까닭을 들어 봐요.","다른 두 친구는 예의 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#21','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C9',3,'mc','auto','상자를 읽고 답해 보세요. 앞면에 담긴 내용을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X14','K2-1-u6-X13']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"상자를 읽고 답해 보세요. 앞면에 담긴 내용을 바르게 말한 것은 어느 것인가요?","options":[{"t":"제목과 인상 깊은 장면 그림","correct":true},{"t":"수빈이의 생각과 까닭","mis":"K2-1-u6-X14"},{"t":"수빈이의 전화번호","mis":"K2-1-u6-X13"}],"explanation":["앞면에는 제목과 인상 깊은 장면을 담았어요.","다른 보기는 상자의 내용과 맞지 않거나 책과 상관없어요.","상자의 면을 돌려 가며 살펴요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#22','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":22,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"샤워","correct":true},{"t":"물","mis":"K2-1-u6-X16"},{"t":"아껴","mis":"K2-1-u6-X16"}],"explanation":["「샤워」는 한 번만 나와요.","다른 두 낱말은 제목에 있거나 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#23','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 컵에 물을 받아 이를 닦는다 · 비누칠할 때 수도꼭지를 잠근다 · 샤워는 짧게 한다 → 여러 방법으로 물을 아껴 쓰자.","scoring_points":["중심 문장을 빠짐없이 찾았는가","예나 까닭을 덧붙인 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["중심 문장 찾기.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#24','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C6',4,'essay','teacher','대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 개구리 — 목소리가 커서 잘 알린다. 거북 — 차분해서 꼼꼼히 살핀다. 나는 거북에게 찬성해요. 왜냐하면 반장은 실수 없이 살피는 것이 중요하기 때문이에요.","scoring_points":["두 인물의 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가","찬성하는 생각과 내 까닭을 썼는가"]},"explanation":["인물의 생각.","짝이 되는 까닭.","내 생각과 까닭."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#25','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C8',4,'essay','teacher','「체험학습으로 어디에 가면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"「체험학습으로 어디에 가면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.","answer_guide":{"answer":"예: 나는 과학관에 가면 좋겠다고 생각해. 왜냐하면 직접 실험을 해 볼 수 있고, 비가 와도 안에서 볼 수 있기 때문이야.","scoring_points":["내 생각을 분명히 썼는가","생각을 뒷받침하는 까닭을 두 가지 썼는가","알맞은 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","까닭 두 가지.","예의 바른 꼴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
